export const introductionArabic = [{"id":"vce-1-1","promptHash":"682b9b5f1599b8dbc2e953cc8b86dd4035f14929fbde5c8c22ecdb7c547ffb9a","fields":{"prompt":{"sourceHash":"682b9b5f1599b8dbc2e953cc8b86dd4035f14929fbde5c8c22ecdb7c547ffb9a","ar":["تعمل مديراً بدوام جزئي في منظمة ذات هيكل مصفوفي ضعيف. ويزيد مديرك الوظيفي أعباء عملك بتكليفك بإدارة مشروع لفكرة عمل جديدة. بعد مراجعة دراسة الجدوى التجارية، تدرك ضرورة تعيين موظفين جدد لتنفيذ المشروع. ما القيد الذي ستعمل في إطاره، إن وُجد، فيما يتعلق بتعيين موظفين إضافيين؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"aebee8f4d32539380d015b6fddc26da8519e500f6edecebbdfc3f244b121cb0f","ar":["C. سيكون المدير الوظيفي مسؤولاً عن تعيين الموظفين.","تستلزم الإجابة الصحيحة معرفة الفروق بين أنواع الهياكل التنظيمية. في الهيكل المصفوفي الضعيف، غالباً ما يكون دور مدير المشروع بدوام جزئي، ويفتقر إلى الصلاحيات المرتبطة بدور متفرغ للمشروع. وبسبب محدودية سلطة مدير المشروع على الموارد في هذا الهيكل، يحتفظ المدير الوظيفي بمسؤولية إدارة موارد الإدارة وتوفيرها. لذلك، إذا احتجت إلى موظفين إضافيين، فعادةً ما يكون قرار التعيين من اختصاص المدير الوظيفي الذي يتحكم في مجموعة الموارد المتاحة.","الخيارات الأخرى غير صحيحة:","A. عادةً ما تفوّض الإدارة العليا مسؤوليات إدارة الموارد والتعيين إلى رؤساء الإدارات الوظيفية، بدلاً من مباشرتها بنفسها لتلبية احتياجات التوظيف في كل مشروع.","B. رغم اهتمام أصحاب المصلحة بنتائج المشروع، فإنهم ليسوا مسؤولين عن الإجراءات التشغيلية الداخلية لتعيين الموظفين داخل إدارة وظيفية.","D. لا يتمتع مدير المشروع في الهيكل المصفوفي الضعيف بصلاحية رسمية لتعيين الموظفين. وتظل هذه السلطة بيد المدير الوظيفي الذي يشرف على الموظفين وميزانية الإدارة."]},"option-0":{"sourceHash":"55560ff1dfa6cabe7a15416fba59ba825f9478e389d46292d07c35139b3fd862","ar":["ستكون الإدارة العليا مسؤولة عن تعيين الموظفين."]},"option-1":{"sourceHash":"e7f9fc0c662dc6928548faf1e0248fb56e6cb739879659a51d7cd40451d9ed17","ar":["سيكون جميع أصحاب المصلحة مسؤولين عن تعيين الموظفين."]},"option-2":{"sourceHash":"3063f2d2f29a90a7867ade6307ebdc3ce14b7b9a1836cb021ad8336b6501b2e0","ar":["سيكون المدير الوظيفي مسؤولاً عن تعيين الموظفين."]},"option-3":{"sourceHash":"ada8dc38df56ee3b121bba8f27968327b963951a2a7f757e34e70c595085d6df","ar":["ستكون أنت، بصفتك مدير المشروع، مسؤولاً عن تعيين الموظفين."]}}},{"id":"vce-1-2","promptHash":"83ef661e8ed0e7a3cd7dd8b3924cc0bada8eff8b34540e6aeb03d384ca4f6a3d","fields":{"prompt":{"sourceHash":"83ef661e8ed0e7a3cd7dd8b3924cc0bada8eff8b34540e6aeb03d384ca4f6a3d","ar":["تولى مدير مشروع للتو مسؤولية مشروع لتطوير منتج باستخدام دورة حياة هجينة. في هذا المشروع، متطلبات المكونات المادية ثابتة، بينما لا تزال متطلبات البرمجيات تتطور. كيف ينبغي لمدير المشروع تطبيق دورة الحياة الهجينة على هذا المشروع؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"5445c7c788b8c64ea6105d58e3f48f7ae881dcd63013403aecb396eb1cbb5e15","ar":["C. تطوير المكونات المادية وفق دورة حياة تنبؤية، واستخدام دورة حياة تكيفية للبرمجيات.","تجمع دورة حياة التطوير الهجينة بين دورتي الحياة التنبؤية والتكيفية. في دورة الحياة التنبؤية، يُحدَّد نطاق المشروع ووقته وتكلفته في المراحل المبكرة. أما في دورة الحياة التكيفية، فيُحدَّد النطاق التفصيلي ويُعتمَد بصورة تكرارية طوال المشروع. في الدورة الهجينة، تتبع مكونات المشروع المعروفة جيداً أو ذات المتطلبات الثابتة نهجاً تنبؤياً، بينما تتبع المكونات التي لا تزال تتطور نهجاً تكيفياً. وبما أن متطلبات المكونات المادية ثابتة ومتطلبات البرمجيات متغيرة، ينبغي تطوير المكونات المادية باستخدام دورة حياة تنبؤية، والبرمجيات باستخدام دورة حياة تكيفية.","الخيارات الأخرى غير صحيحة:","A. تحديد نطاق المكونات المادية والبرمجيات معاً بصورة تكرارية غير صحيح، لأنه يتعامل مع متطلبات المكونات المادية الثابتة كما لو كانت متغيرة، مما قد يؤدي إلى تكاليف غير ضرورية وتأخيرات في الجدول الزمني نتيجة إدخال تغييرات تكرارية على مكونات مستقرة.","B. استخدام دورة تنبؤية للبرمجيات وتكيفية للمكونات المادية يعكس ما يتطلبه سياق المشروع؛ فالمكونات المادية ذات المتطلبات الثابتة تناسبها الدورة التنبؤية، والبرمجيات ذات المتطلبات المتطورة تناسبها الدورة التكيفية.","D. تحديد نطاق المكونات المادية والبرمجيات معاً أثناء التخطيط الأولي يتجاهل الطبيعة المتغيرة لمتطلبات البرمجيات. وفرض نطاق تنبؤي جامد على مكونات برمجية متطورة غالباً ما يؤدي إلى إعادة عمل واسعة وعدم تلبية احتياجات المستخدمين."]},"option-0":{"sourceHash":"b2968e4d7350194874a2c757aaaaaa38fcfd0bb288f2c4d66a9d02e039a7f7b6","ar":["ينبغي تحديد نطاق كلٍّ من المكونات المادية والبرمجيات بصورة تكرارية"]},"option-1":{"sourceHash":"54e28db195a0eb6e1fba8757d4f324373f9db7c0f45a59dbb94eab6401d25fb0","ar":["تطوير البرمجيات وفق دورة حياة تنبؤية، واستخدام دورة حياة تكيفية للمكونات المادية"]},"option-2":{"sourceHash":"d814fb232384fb704c5f49262b806f2714fb0e309a7f3015be82594ee4baa2a6","ar":["تطوير المكونات المادية وفق دورة حياة تنبؤية، واستخدام دورة حياة تكيفية للبرمجيات"]},"option-3":{"sourceHash":"99cc56ada8bac9e6edd66b9479040b7e484285993a36854434055cf4ffa911e4","ar":["ينبغي تحديد نطاق كلٍّ من المكونات المادية والبرمجيات أثناء التخطيط الأولي للمشروع"]}}},{"id":"vce-1-3","promptHash":"185047e5581d5ac53a42831fcaa515a40dd73c1a8460281c3461db130599f418","fields":{"prompt":{"sourceHash":"185047e5581d5ac53a42831fcaa515a40dd73c1a8460281c3461db130599f418","ar":["أنت مدير مشروع يتبع فيه أعضاء الفريق هيكلاً مزدوجاً للتبعية الإدارية. فإلى جانب تبعيتهم لك، يتبعون أيضاً مديرهم الوظيفي. كما يُتوقَّع منهم إنجاز أعمال المشروع إلى جانب أعمال الإدارة. ما نوع الهيكل التنظيمي الذي تعمل فيه؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"de0ac7066b20a63fe9f774728f82901b6ae7498aa86be762a607e5931adf830b","ar":["A. مصفوفي","يتميز الهيكل التنظيمي المصفوفي بعلاقة تبعية مزدوجة؛ إذ يتبع أعضاء الفريق مديراً وظيفياً مسؤولاً عن إدارتهم ومسارهم المهني، ومدير مشروع مسؤولاً عن أهداف المشروع المحددة. وفي هذه البيئة، يجب على أعضاء الفريق توزيع وقتهم بين مهام إداراتهم المستمرة وتكليفاتهم في المشروع.","الخيارات الأخرى غير صحيحة:","B. في المنظمة القائمة على المشاريع، يتبع أعضاء الفريق مدير المشروع بصفة أساسية. ويتمتع مدير المشروع بصلاحيات واسعة، ويُخصَّص الموظفون عادةً للمشروع بدوام كامل بدلاً من توزيع وقتهم بينه وبين أعمال الإدارة الوظيفية.","C. في المنظمة الوظيفية، يتبع أعضاء الفريق مديراً وظيفياً واحداً. ولا يوجد هيكل تبعية مزدوجة، وتكون سلطة مدير المشروع عموماً محدودة جداً أو منعدمة، وتظل معظم الأعمال داخل حدود الإدارة الوظيفية.","D. تجميع الفريق في موقع واحد (Tight Matrix) ليس هيكلاً تنظيمياً، بل أسلوب لوضع أعضاء الفريق في مواقع متقاربة فعلياً لتحسين التواصل والتكامل بينهم، بغض النظر عن الهيكل التنظيمي العام."]},"option-0":{"sourceHash":"76a2171c057b730faadfe35296593f0fddc52736d2427a9f55ac8b3d375e3bf5","ar":["مصفوفي"]},"option-1":{"sourceHash":"0a621d00f81d80ad2233d26e6b6c923b997f34b3b6cb66c06fd20f5731408b84","ar":["قائم على المشاريع"]},"option-2":{"sourceHash":"b6656595756edfce13e5399ee5da30f62daf688b23ed0af5279a2481cf528358","ar":["وظيفي"]},"option-3":{"sourceHash":"eda5e0a8f63863fc9eebcb63ca4299deb5f66fb3ab6bf56529760a78d9e9a20c","ar":["تجميع الفريق في موقع واحد (Tight Matrix)"]}}},{"id":"vce-1-4","promptHash":"bb5c374a23d047dcb9c53bce8c334e19881c155578ffc9e94911c825f2c6391d","fields":{"prompt":{"sourceHash":"bb5c374a23d047dcb9c53bce8c334e19881c155578ffc9e94911c825f2c6391d","ar":["أيٌّ من وثائق الأعمال التالية يبرر سبب التصريح بالمشروع؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"119c4a74cf9ecccf681ba88668da60c7035eed26fb863f0176316033802c1dc7","ar":["D. دراسة الجدوى التجارية (Business Case)","دراسة الجدوى التجارية هي الوثيقة الأساسية التي توفر المعلومات اللازمة لتحديد ما إذا كان المشروع يستحق الاستثمار المطلوب. وتتضمن عادةً الحاجة التجارية، وتحليل التكلفة والمنفعة، والمبرر الاستراتيجي للتصريح بالمشروع. وتشكل هذه الوثيقة أساس إعداد ميثاق المشروع.","الخيارات الأخرى غير صحيحة:","A. ميثاق المشروع هو الوثيقة التي تصرّح رسمياً بوجود المشروع وتمنح مديره صلاحية استخدام موارد المنظمة في أنشطته. وهو يستند إلى دراسة الجدوى التجارية، وليس الوثيقة التي تقدم مبرر التصريح الأولي نفسه.","B. بيان نطاق العمل وثيقة تصف المنتجات أو الخدمات أو النتائج التي سيقدمها المشروع. وهو يصف النطاق، لا المبرر التجاري للتصريح بالمشروع.","C. خطة إدارة المشروع وثيقة تصف كيفية تنفيذ المشروع ومراقبته وضبطه. وتُعدّ بعد التصريح بالمشروع بالفعل."]},"option-0":{"sourceHash":"a78758a9658d87d4fc2ec17f565b2445a7bc17e740defdba71a8f7476603cf4e","ar":["ميثاق المشروع."]},"option-1":{"sourceHash":"5b8c728489cf9792c7786f87e6ec3bcea814e8e3bef9c313f5a548c22f3fb1c4","ar":["بيان نطاق العمل."]},"option-2":{"sourceHash":"db5638092869e3e5cde9a4cb8e45b2578d7e123b4edca708195756a9a9bf4d53","ar":["خطة إدارة المشروع."]},"option-3":{"sourceHash":"79ee36f21b97cdf1d26caed96b9cd16045e3c245acee111a7a614bb1815d5026","ar":["دراسة الجدوى التجارية"]}}},{"id":"vce-1-5","promptHash":"55e0cf8684c26dd19daa61abb6300046aa2fb7eaa2313db3de1bf022629cd22f","fields":{"prompt":{"sourceHash":"55e0cf8684c26dd19daa61abb6300046aa2fb7eaa2313db3de1bf022629cd22f","ar":["ما الفرق بين دورة الحياة التنبؤية ودورة الحياة التكيفية؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"733e11ebe58427b86755db209aed7e7c4e61c64931d05eb4bb11e72e1ef079a4","ar":["A. دورة الحياة التنبؤية تقودها الخطة؛ ودورة الحياة التكيفية يقودها التغيير.","في دورة الحياة التنبؤية، أو الشلالية (Waterfall)، يُحدَّد نطاق المشروع ووقته وتكلفته في المراحل المبكرة. ويكون التخطيط شاملاً ويُنجَز مقدماً، لذا تقودها الخطة. وعلى العكس، صُممت دورات الحياة التكيفية، أو الرشيقة (Agile)، للاستجابة لمستويات مرتفعة من التغيير وعدم اليقين. ويُحدَّد النطاق ويُعتمَد بصورة تكرارية، ويعدّل الفريق نهجه بناءً على التغذية الراجعة وتطور المتطلبات، ولذلك يقودها التغيير.","الخيارات الأخرى غير صحيحة:","B. هذا الوصف غير دقيق؛ فدورات الحياة التكيفية لا تتوقف ببساطة عند نفاد المال، بل تستخدم فترات زمنية محددة، أي تكرارات، لتقديم القيمة تدريجياً، وتستمر ما دامت تقدم قيمة للأعمال.","C. يصف هذا الخيار التطوير التكراري بطريقة تخلط بين الأنماط التنبؤية والتغييرات التكيفية. ولا تتبع دورات الحياة التنبؤية بالضرورة نمط «التكرار» نفسه الذي تتبعه الدورات التكيفية، كما أن الدورات التكيفية تقودها تغذية أصحاب المصلحة الراجعة والأولويات المتغيرة، لا مجرد مقاييس نمو الأداء.","D. يوجد فرق واضح بين النهجين في كيفية التعامل مع النطاق والمخاطر وإشراك أصحاب المصلحة."]},"option-0":{"sourceHash":"255a49ba4ac7c2b9343b681644fc38dbdc7f91e10e80402d60b561bdec4756de","ar":["دورة الحياة التنبؤية تقودها الخطة؛ ودورة الحياة التكيفية يقودها التغيير."]},"option-1":{"sourceHash":"76fc208d425a289370a8af6a4865b176ce493310d387ba1ac12b2d0a337694fb","ar":["تتنبأ دورة الحياة التنبؤية بإتمام المشروع؛ أما دورة الحياة التكيفية فتنهي المشروع عند نفاد المال."]},"option-2":{"sourceHash":"5327a028594d6ad7e31fcc556d77af41a2358fded654416f618a1f5b51332470","ar":["يتبع النهج التنبؤي النمط نفسه في كل تكرار، بينما تغيّر دورة الحياة التكيفية نهجها بناءً على نمو أداء نتائج المشروع."]},"option-3":{"sourceHash":"b20abc080666b70cd6920624e1b9ca7cb108a279d65460dc931a8a7b4dddeb0e","ar":["لا يوجد فرق."]}}},{"id":"vce-1-6","promptHash":"fd3bca274ea6ecea519d3b6259801f009472b69c201eab857a1baa4ea82eeec3","fields":{"prompt":{"sourceHash":"fd3bca274ea6ecea519d3b6259801f009472b69c201eab857a1baa4ea82eeec3","ar":["بأيٍّ من المصطلحات التالية يُعرَف قرار الانتقال من مرحلة إلى أخرى؟ (اختر إجابتين.)"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"b6d2734e50feb98cb6d8423e2796764b5e984c829151b4b5a6d7f1c970455be2","ar":["A. نقطة الإيقاف (Kill Point)","D. بوابة المرحلة (Phase Gate)","في إدارة المشاريع، يُضبَط الانتقال بين مراحل المشروع رسمياً من خلال المراجعات. وبوابة المرحلة، التي تُسمّى أيضاً مراجعة المرحلة أو بوابة الانتقال أو مراجعة المعلم الرئيسي، هي نقطة تحقق منظمة يُقيَّم فيها أداء المشروع وتقدمه لتحديد ما إذا كان ينبغي الانتقال إلى المرحلة التالية أو تعديل المشروع أو إنهاؤه. أما نقطة الإيقاف فهي النتيجة المحددة لمراجعة بوابة المرحلة عندما يُتخذ قرار إنهاء المشروع أو المرحلة لعدم استمرار استيفاء الأهداف الاستراتيجية أو معايير الأداء التي تبرر المزيد من الاستثمار.","الخيارات الأخرى غير صحيحة:","B. عتبة الاستمرار ليست مصطلحاً معيارياً لوصف نقطة الانتقال بين مراحل المشروع.","C. رغم أن «نقطة نهاية المرحلة» قد تُستخدم في الحديث العام لوصف انتهاء مرحلة، فإنها ليست المصطلح المهني الرسمي لنقطة اتخاذ القرار أو قرار الإنهاء المرتبط بها."]},"option-0":{"sourceHash":"290d822ef4a4e8a2fa2f733c92450b3adacacb1e0b40b95f7c245cc1aebdfa9c","ar":["نقطة الإيقاف (Kill Point)"]},"option-1":{"sourceHash":"5db06c8768cadac2713384e1fe1529c8b065bbd438deb40ef1a01d485729e88e","ar":["عتبة الاستمرار"]},"option-2":{"sourceHash":"8f270ad26e03135ef84738bb068d14cd6937c6a709ad9bac1dde22a6f7a6d0e2","ar":["نقطة نهاية المرحلة"]},"option-3":{"sourceHash":"35ea95339cfeb93db2a45f16a20b3c8e551e77e8b7c92487742d3720d975c246","ar":["بوابة المرحلة (Phase Gate)"]}}},{"id":"vce-1-7","promptHash":"9981781f9009e16789f37d563fad386a94c194a62ed942621d4fa99da47620cc","fields":{"prompt":{"sourceHash":"9981781f9009e16789f37d563fad386a94c194a62ed942621d4fa99da47620cc","ar":["أيٌّ مما يلي يصف العلاقة الأكثر شيوعاً بين المراحل في المشاريع متعددة المراحل؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"f9aa816ffd0df5ba471f42d4378ebed3bb9b2d5ab1c510a24e9af02205e25553","ar":["A. تتابعية","تمثل المراحل في إدارة المشاريع مجموعات منطقية من أنشطة المشروع. والعلاقة التتابعية هي الأكثر شيوعاً بين المراحل، حيث يجب إتمام مرحلة، أو اعتماد تسليماتها، قبل بدء المرحلة التالية. ويُستخدم هذا النهج عادةً لأنه يقلل عدم اليقين ويوفر نقاط تحقق واضحة للحوكمة عند الانتقال بين مراحل المشروع.","الخيارات الأخرى غير صحيحة:","B. «منظّمة» ليست مصطلحاً رسمياً في إدارة المشاريع لتعريف العلاقات بين المراحل.","C. «نهاية إلى بداية» علاقة اعتماد منطقية تُستخدم تحديداً بين أنشطة الجدول الزمني ضمن مخططات الأسبقية، لا لوصف العلاقة عالية المستوى بين مراحل المشروع.","D. «غير متداخلة» تصف نتيجة العلاقة التتابعية، لكنها ليست المصطلح المعياري لتصنيف العلاقة نفسها. وقد تكون المراحل متداخلة، كما في التتبع السريع (Fast-Tracking)، أو تكرارية بحسب احتياجات دورة حياة المشروع."]},"option-0":{"sourceHash":"332ddf8b25deb00c623e0ddb232301303c84dd522f6097911154d706366f3b2c","ar":["تتابعية"]},"option-1":{"sourceHash":"e692fa5ee5063aefdba9a8788096a82f62a25a8887b0d719004eb4b93ca3f6d2","ar":["منظّمة"]},"option-2":{"sourceHash":"5920806f20d6952ecf6202ae0d4a6336472b9d4c11bd2c749836d5d448d56589","ar":["نهاية إلى بداية (Finish-to-Start)"]},"option-3":{"sourceHash":"3e76448814456d7ea409fc461fc0305f3544794ee52b218c3cffbd86f6fb362a","ar":["غير متداخلة"]}}},{"id":"vce-1-8","promptHash":"f066ad2529fb560ba2ec21f09338eb126f908442f0e4196230dc68c94db60a8a","fields":{"prompt":{"sourceHash":"f066ad2529fb560ba2ec21f09338eb126f908442f0e4196230dc68c94db60a8a","ar":["بالإضافة إلى الإدارات المذكورة في السيناريو، يوجد في شركتك أيضاً مدير لإدارة المشاريع يشرف على جميع المشاريع الجارية. وبصفتك أحد مديري المشاريع، تتبع مباشرةً إدارة المشاريع، لكنك تتشارك الموظفين مع إدارات أخرى. ما نوع الهيكل التنظيمي الذي يصفه ذلك؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"6e7bcd3810818225cc694fce2e8e07c8ec7cd5440c695cf71dcde076e0f96ce9","ar":["A. مصفوفي","يتميز الهيكل التنظيمي المصفوفي بالتبعية المزدوجة، حيث يتبع أعضاء الفريق مديراً وظيفياً ومدير مشروع معاً. والسمة الحاسمة في هذا السيناريو هي مشاركة الموظفين بين إدارات مختلفة لدعم المشاريع مع الإبقاء على خطوط التبعية الوظيفية، وهي سمة مميزة للمنظمة المصفوفية.","الخيارات الأخرى غير صحيحة:","B. في المنظمة الوظيفية، يتمتع مدير المشروع بسلطة محدودة جداً، ولا توجد عادةً إدارة متخصصة للمشاريع تتشارك الموارد على مستوى المنظمة بأكملها.","C. في المنظمة القائمة على المشاريع، يتبع أعضاء الفريق مدير المشروع بصفة أساسية، وغالباً ما تُخصَّص الموارد للمشروع بدلاً من مشاركتها بين إدارات وظيفية متعددة.","D. رغم وجود الهيكل المركّب، الذي يجمع أنواعاً مختلفة من الهياكل، فإن «المصفوفي» هو المصطلح الأدق والأكثر تحديداً للهيكل الذي يتشارك فيه المديرون الوظيفيون ومديرو المشاريع السلطة والموظفين."]},"option-0":{"sourceHash":"76a2171c057b730faadfe35296593f0fddc52736d2427a9f55ac8b3d375e3bf5","ar":["مصفوفي"]},"option-1":{"sourceHash":"b6656595756edfce13e5399ee5da30f62daf688b23ed0af5279a2481cf528358","ar":["وظيفي"]},"option-2":{"sourceHash":"0a621d00f81d80ad2233d26e6b6c923b997f34b3b6cb66c06fd20f5731408b84","ar":["قائم على المشاريع"]},"option-3":{"sourceHash":"8e3588157fcf8d7c32058feba195c8dfa8c61248b12807b660562c1997d2ce6a","ar":["مركّب"]}}},{"id":"vce-1-9","promptHash":"36b7311e8df130e5e79da63d0862cb47ef3dcbdec8569d92b95329235e44b52d","fields":{"prompt":{"sourceHash":"36b7311e8df130e5e79da63d0862cb47ef3dcbdec8569d92b95329235e44b52d","ar":["في بداية تأسيس المشروع، تقضي مديرة المشروع وقتاً في البحث عن بيانات تاريخية قد تساعد في تخطيط المشروع الجديد. وتبحث عن أمثلة لوثائق مشاريع مماثلة أُنجزت سابقاً كي تستخدمها قوالب للمشروع الجديد. كما تبحث عن معلومات عن العمليات والإجراءات المعتمدة التي ستساعد على سير المشروع بسلاسة أكبر. ما المصطلح الذي يُطلَق على هذه العناصر؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"f8e5df70386ed2cea4ba60a720ec84b4191e7f9f66ecab3fe4957a099e07eacc","ar":["B. أصول العمليات التنظيمية (OPAs)","تشمل أصول العمليات التنظيمية (OPAs) الخطط والعمليات والسياسات والإجراءات وقواعد المعرفة الخاصة بالمنظمة المنفذة والتي تستخدمها. وتُصنَّف إلى مجموعتين:","العمليات والسياسات والإجراءات: مثل القوالب والإرشادات المعيارية والضوابط المالية.","قواعد المعرفة التنظيمية: مثل المعلومات التاريخية والدروس المستفادة وملفات المشاريع.","توفر هذه الأصول الإرشاد الأساسي والسياق التاريخي اللذين يؤثران في كيفية إدارة المشروع.","الخيارات الأخرى غير صحيحة:","A. التفصيل التدريجي أسلوب تخطيط يقوم على تحسين خطة إدارة المشروع وتفصيلها باستمرار كلما توفرت معلومات أكثر وتقديرات أدق. وهو إجراء يُنفَّذ أثناء التخطيط، وليس مجموعة من الأصول.","C. تشير العوامل البيئية للمؤسسة (EEFs) إلى ظروف لا تخضع لسيطرة فريق المشروع، وتؤثر في المشروع أو تقيّده أو توجهه. وتشمل أمثلتها الثقافة التنظيمية وظروف السوق والبنية التحتية القائمة. ورغم تأثيرها في المشروع، فإنها ظروف خارجية أو عامة على مستوى الشركة، وليست القوالب والوثائق الداخلية التي تبحث عنها مديرة المشروع.","D. الاجتماع الاستعادي مراجعة يجريها الفريق لفحص العمليات والنتائج وتكييفها أثناء التكرار أو في نهايته. ورغم أن مخرجاته قد تصبح من أصول العمليات التنظيمية، فإن المصطلح نفسه لا يعبّر عن مجموعة القوالب والإجراءات."]},"option-0":{"sourceHash":"d41f5ee296710f315d6efa304baf72076cb925051d9f28bff00ac9fcad01eeef","ar":["التفصيل التدريجي"]},"option-1":{"sourceHash":"187be3e5cc1ddb2a4de2006a87579bc1a90538a3102b07004e5e53014d5369b3","ar":["أصول العمليات التنظيمية (OPAs)."]},"option-2":{"sourceHash":"1a6ef8658853d0552a5cf96f60faabf02b02d4956240de158f52a547f9f7e857","ar":["العوامل البيئية للمؤسسة (EEFs)"]},"option-3":{"sourceHash":"13c3e4d84cbc5b546c8110b08ba22f4e74a75bc3d0ad7b3e866bfa2e6a8c780d","ar":["الاجتماع الاستعادي (Retrospective)"]}}},{"id":"vce-1-10","promptHash":"a97cfc07faea0159147aac8b3ec794041507cd564e6c7b66cd357271a42aff4c","fields":{"prompt":{"sourceHash":"a97cfc07faea0159147aac8b3ec794041507cd564e6c7b66cd357271a42aff4c","ar":["تعمل في مشروع كبير مقسّم إلى المراحل التالية: دراسة الجدوى، والتصور المبدئي، والتصميم، والنموذج الأولي، والبناء. وتريد استخدام مجالات التركيز (Focus Areas) مع هذه المراحل المختلفة. ما النهج الموصى به؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"340b0c12ae70f65091d86b4405f6f03e94503979ebf689c97f529dc488e77969","ar":["A. تكرار تطبيق مجالات التركيز الخمسة كلها في كل مرحلة","تؤدي مراحل المشروع ومجالات التركيز، التي يُشار إليها غالباً في سياق مجالات الأداء أو مجموعات العمليات، أغراضاً مختلفة. فمرحلة المشروع تمثل مجموعة منطقية من الأنشطة لإنتاج تسليم محدد، بينما تمثل مجالات التركيز الموضوعات الإدارية المتكاملة الواجب تطبيقها طوال عمر المشروع. ولضمان الإدارة الشاملة والحوكمة وتقديم القيمة، تتطلب كل مرحلة تطبيق جميع مجالات التركيز، بصرف النظر عن حجم تلك المرحلة أو محتواها.","الخيارات الأخرى غير صحيحة:","B. إعادة تسمية المراحل لتطابق مجالات التركيز خطأ جوهري. فالمراحل تحدد ما يُنتَج، أي العمل، بينما تحدد مجالات التركيز كيفية إدارة ذلك العمل ودعمه بفاعلية.","C. لا يُوصى بتجاوز مجالات التركيز؛ فإغفال موضوعات إدارية مثل «إشراك أصحاب المصلحة» أو «التخطيط» أو «عدم اليقين/المخاطر» في أي مرحلة قد يؤدي إلى جوانب مغفلة وضعف الضبط وعدم تحقيق الأهداف.","D. تخصيص مجال تركيز واحد فقط لكل مرحلة غير ممكن، لأن المرحلة جزء من دورة الحياة يحتاج إلى السياق الإداري الكامل كي يعمل؛ فعلى سبيل المثال، يجب تطبيق جميع مجالات التركيز على مرحلة «التصميم» كما على مرحلة «البناء»."]},"option-0":{"sourceHash":"01f1a583012eeb8c53743810d777b6043c752c761176ee8a7646c4775293413a","ar":["تكرار تطبيق مجالات التركيز الخمسة كلها في كل مرحلة"]},"option-1":{"sourceHash":"ee1ae155099c965d43f996bf29858f88e3d58bb7d4bb29ebe5cc3c0e5eaa6607","ar":["إلغاء تقسيم المشروع إلى مراحل وإعادة تسمية كل مرحلة باسم أحد مجالات التركيز"]},"option-2":{"sourceHash":"699f0efea265a1a49f9faa9ea7f7d353a2107235d5204af0d693b67dd25955a2","ar":["تجاوز بعض مجالات التركيز لأنها لا تنطبق على مشروع كبير"]},"option-3":{"sourceHash":"23aacc183d24c4c9edc7f5c6d1cd0d60e5ed1bddc147eca2fb142c8918d84569","ar":["تخصيص مجال تركيز واحد لكل مرحلة"]}}},{"id":"vce-1-11","promptHash":"7093257486095a58ac71066ef7ba203f8747054dbe1474d34e1f2050815406e1","fields":{"prompt":{"sourceHash":"7093257486095a58ac71066ef7ba203f8747054dbe1474d34e1f2050815406e1","ar":["أيٌّ من العبارات التالية يصف بدقة أكبر سيناريو مشروع نموذجي؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"fc4e9feeaea1bf41a45e292bae53f7ce5d4533209154384289a9ebfa6da93761","ar":["C. يبلغ عدد العاملين ذروته أثناء مرحلة تنفيذ المشروع.","تكون مستويات التوظيف منخفضة عموماً أثناء مرحلتي البدء والتخطيط، ثم ترتفع بوضوح إلى ذروتها أثناء التنفيذ حين يُنجَز معظم عمل المشروع، وبعد ذلك تتراجع تدريجياً أثناء مرحلتي المراقبة والإغلاق.","الخيارات الأخرى غير صحيحة:","A. رغم أن هذا إجراء شائع للتخفيف من المخاطر، فإنه ليس قاعدة ملزمة دائماً. فكثيراً ما تستخدم المشاريع التتبع السريع، أي تداخل المراحل، لاختصار الجدول الزمني، مما يسمح ببدء المرحلة التالية قبل اكتمال السابقة تماماً.","B. يكون تأثير أصحاب المصلحة في الواقع في أعلى مستوياته عند بداية المشروع، وينخفض تدريجياً مع تقدم المشروع نحو الإنجاز. ويكون التأثير في اتجاه المشروع أسهل وأقل تكلفة بكثير في المراحل المبكرة.","D. تكون تغييرات نطاق المشروع أقل تكلفة في المراحل الأولى. ومع تقدم المشروع، ترتفع تكلفة إجراء التغييرات بدرجة كبيرة بسبب تراكم تكاليف الأعمال المنجزة وتعقيد دمج المتطلبات الجديدة في خطة قائمة."]},"option-0":{"sourceHash":"bad647206b86ddc6bd409c1b7d00ee969b929076c4996284fc23fdeb3a81a162","ar":["يجب ألا تبدأ المرحلة التالية من المشروع مطلقاً قبل مراجعة تسليمات المرحلة السابقة واعتمادها بالكامل."]},"option-1":{"sourceHash":"11b4d8077aeab219005e70788f6ef4d8eec27aaf727b5201e44456ef5fa1a359","ar":["يظل تأثير أصحاب المصلحة ثابتاً طوال المشروع."]},"option-2":{"sourceHash":"97912029ee3c77cd8ff76036b777a88f18aa15f3aa51e4fb84eb91739ba46a7c","ar":["يبلغ عدد العاملين ذروته أثناء مرحلة تنفيذ المشروع."]},"option-3":{"sourceHash":"54828c85c9576db3c9b5f049ac746dea50a95ae8093cef8df8d81887076d0653","ar":["تكون تغييرات نطاق المشروع في مراحله الأولى مرتفعة التكلفة جداً."]}}},{"id":"vce-1-12","promptHash":"5d61bcc4eab6f4d444f9891e3f6828f04824a78e576885e5ad33fe77babaddca","fields":{"prompt":{"sourceHash":"5d61bcc4eab6f4d444f9891e3f6828f04824a78e576885e5ad33fe77babaddca","ar":["أوصيت بإعداد دراسة جدوى تجارية لكل مشروع في المنظمة، يليها إعداد خطة لإدارة منافع المشروع. من توصي بأن يكون مالك دراسة الجدوى التجارية؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"416c868f2ae07a9a0be73bb4e6520eec3b6ed36e9a7b7a9c2fc279989d5fe918","ar":["D. راعي المشروع","يتحمل راعي المشروع المساءلة عن إعداد دراسة الجدوى التجارية للمشروع والمحافظة عليها. وهو يوفر الموارد والدعم اللازمين للمشروع، ويتحمل مسؤولية ضمان استمرار جدوى الدراسة طوال دورة حياة المشروع. ورغم الدور المحوري لمدير المشروع في تقديم التوصيات والحفاظ على المواءمة والإشراف لضمان اتساق المشروع مع الدراسة، فإن المساءلة النهائية عن دراسة الجدوى التجارية تقع على الراعي.","الخيارات الأخرى غير صحيحة:","A. فريق المشروع مسؤول عن تنفيذ العمل لتحقيق أهداف المشروع، لكنه لا يمتلك عادةً دراسة الجدوى التجارية، فهي وثيقة استراتيجية.","B. مجلس ضبط التغيير (CCB) مسؤول عن مراجعة تغييرات المشروع وتقييمها والموافقة عليها أو تأجيلها أو رفضها، لكنه ليس مالك دراسة الجدوى التجارية الأولية.","C. مدير المشروع مسؤول عن إدارة المشروع وضمان استمرار توافق تسليماته مع دراسة الجدوى التجارية، لكنه ليس عادةً «المالك» الذي يبرر التصريح بالمشروع واستمرار الاستثمار فيه؛ فهذا دور الراعي."]},"option-0":{"sourceHash":"bf56b939ea26cc41a3cabe2bdc69d3268c6e2599deaccf4f98577a184202c0d3","ar":["فريق المشروع"]},"option-1":{"sourceHash":"7d63eb3536267086c0841f0e17ebe3c372ca707f0396f53a891dc2d0c3ae58c5","ar":["مجلس ضبط التغيير"]},"option-2":{"sourceHash":"a9cf46e3db81c132fb99feb2f5a1f49398eccb33dcee1cbd7fb37e6569e02f4d","ar":["مدير المشروع"]},"option-3":{"sourceHash":"2faa02ff384a655b039319508039201da390b08ccb8e355182f33a089981cc85","ar":["راعي المشروع"]}}},{"id":"vce-1-13","promptHash":"0e3f985379980a3c219c3aa337670a31df5aa3d03cbccdf736aa82e681d09e1a","fields":{"prompt":{"sourceHash":"0e3f985379980a3c219c3aa337670a31df5aa3d03cbccdf736aa82e681d09e1a","ar":["أنشأت منظمة مكتب إدارة مشاريع رقابياً (Controlling PMO). وكانت أولى مهامه تحديث إرشادات امتثال المشاريع داخل المنظمة. أيٌّ مما يلي يستطيع المكتب فرضه؟ (اختر ثلاث إجابات.)"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"d1ff836161692b7e716d6a9af6453d79b4101842e6530d6dba91d92e204bb2c9","ar":["A. استخدام منهجيات محددة لإدارة المشاريع","B. اعتماد قوالب ونماذج وأدوات محددة","E. الامتثال لأطر الحوكمة","يوفر مكتب إدارة المشاريع الرقابي الدعم والتوجيه، مع اشتراط الامتثال أيضاً. ويضمن هذا الإلزام اتباع المشاريع للمعايير التنظيمية. وتشمل مجالات الإلزام الشائعة استخدام أطر أو منهجيات محددة لإدارة المشاريع، والاعتماد الإلزامي للقوالب والنماذج والأدوات، والالتزام بأطر الحوكمة التنظيمية المعتمدة.","الخيارات الأخرى غير صحيحة:","C. الالتزام باللوائح الصحية المحلية مسألة تتعلق عادةً بالامتثال القانوني والسلامة على مستوى المنظمة، وليس منهجية أو عملية لإدارة المشاريع يفرضها مكتب إدارة المشاريع.","D. تعيين مديري المشاريع بواسطة المكتب من سمات مكتب إدارة المشاريع التوجيهي (Directive PMO)، الذي يتولى السيطرة الكاملة على المشاريع عبر إدارتها مباشرةً وتعيين مديريها بنفسه."]},"option-0":{"sourceHash":"49b2eab9c6702d244740acf1133bff425eef80afa5da0a9df290534c26395df4","ar":["استخدام منهجيات محددة لإدارة المشاريع"]},"option-1":{"sourceHash":"088138f2b99d5b1a910a7902f1067e87c1bde86713aae8d15c8137ccdc76044f","ar":["اعتماد قوالب ونماذج وأدوات محددة"]},"option-2":{"sourceHash":"2360c9cb6e2b0db0419739348d71efa65ee7b225ba1bd5cb5d2a02e877ea5366","ar":["الالتزام باللوائح الصحية المحلية"]},"option-3":{"sourceHash":"e9b3427283176e5049c1699dfa6797d9db0d65e99835a4021d41964ec903215e","ar":["تعيين مديري المشاريع بواسطة مكتب إدارة المشاريع"]},"option-4":{"sourceHash":"470ce9c0d45fe9f303f1f3094b9cc4c40c987ad0468c9969eb2b4ff455321733","ar":["الامتثال لأطر الحوكمة"]}}},{"id":"vce-1-14","promptHash":"5a5dc7667979f799e9d037d9de64c617c9a6eac910e726c9ec63584c0a731f5a","fields":{"prompt":{"sourceHash":"5a5dc7667979f799e9d037d9de64c617c9a6eac910e726c9ec63584c0a731f5a","ar":["بدأ للتو مشروع لتحويل منظمة من هيكل تنظيمي وظيفي إلى هيكل قائم على المشاريع. إذا نجح المشروع في تحقيق أهدافه، فما النتائج الأرجح؟ (اختر ثلاث إجابات.)"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"f2da0e3d714d9e95ab4dd0fd56498d46f42888216339bac5608117b638b3a288","ar":["B. ستنتقل المنظمة من حالتها الراهنة إلى الحالة المستقبلية المنشودة.","C. سيتمتع مدير المشروع أو مديرو المشاريع بالسيطرة على ميزانية المشروع.","D. ستزداد سلطة مدير المشروع أو مديري المشاريع على المشاريع بدرجة كبيرة.","الغرض من أي مشروع هو نقل المنظمة من حالة راهنة إلى حالة مستقبلية منشودة. وفي هذا السيناريو، يؤدي الانتقال من الهيكل الوظيفي، حيث يمتلك المديرون الوظيفيون السلطة، إلى الهيكل القائم على المشاريع، حيث يمتلك مديرو المشاريع السلطة، إلى تحولات مهمة: يكتسب مدير المشروع السيطرة على الميزانية، وتزداد سلطته بدرجة كبيرة على موارد المشروع واتخاذ القرارات.","الخيارات الأخرى غير صحيحة:","A. تجميع الموظفين بحسب العمل الذي يؤدونه، كالهندسة والتصنيع، هو تعريف الهيكل التنظيمي الوظيفي، لا الهيكل القائم على المشاريع.","E. يتمتع منسق المشروع عادةً بسلطة محدودة جداً، ويشيع هذا الدور في الهياكل المصفوفية الضعيفة أو الوظيفية. أما في المنظمة القائمة على المشاريع، فعادةً ما يشغل مدير المشروع دوراً قيادياً متفرغاً ذا صلاحيات واسعة، لا مجرد دور تنسيقي."]},"option-0":{"sourceHash":"1ff773e70e30d08d210110741b335ff562ba3ddc6e17dd322dfab85bbb7a110f","ar":["سيُجمَّع الموظفون بحسب العمل الذي يؤدونه، مثل الهندسة والتصنيع وغيرهما"]},"option-1":{"sourceHash":"adad8223d6cb04ffeb334909e05d76faaee513752709bbd2f344a682ade21b43","ar":["ستنتقل المنظمة من حالتها الراهنة إلى الحالة المستقبلية المنشودة."]},"option-2":{"sourceHash":"4d91a3cd8aa3914d799dca983bdf2fd900435bc9fd9326b36f6536a8925c497b","ar":["سيتمتع مدير المشروع أو مديرو المشاريع بالسيطرة على ميزانية المشروع."]},"option-3":{"sourceHash":"5ede06c7bd08b760d7e3069644a89cbd2549b3f87ce8cc20ddf8f3416922dc77","ar":["ستزداد سلطة مدير المشروع أو مديري المشاريع على المشاريع بدرجة كبيرة."]},"option-4":{"sourceHash":"1e458aab828d68e7dd9b495364ea9612c317cb2a9b5b3c7bae9b02ae17ea4a42","ar":["سيُعرَّف دور مدير المشروع أو مديري المشاريع بوصفه منسق مشروع."]}}},{"id":"vce-1-15","promptHash":"0fb9f0a1531672a02fe4ce8dfa8b4f93ec86cc1d6b982f54fbcdc3d3339da805","fields":{"prompt":{"sourceHash":"0fb9f0a1531672a02fe4ce8dfa8b4f93ec86cc1d6b982f54fbcdc3d3339da805","ar":["أثناء اجتماع لمراجعة المشروع، أعرب راعي المشروع عن قلقه من احتمال عدم تحقيق المشروع للنتائج المخططة. وبناءً على ذلك، يقيّم مدير المشروع حالة المشروع.","ما المعلومات التي ينبغي لمدير المشروع استخدامها مؤشراً على أن المشروع يقدم قيمة بالفعل؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"7948e2effb5c3bb0b0a5328605673d586e755d1aed2068f0cabcfd670b4b05dd","ar":["C. توافق المشروع مع خطة إدارة المنافع","خطة إدارة المنافع هي الوثيقة المخصصة لتعريف عمليات إنشاء منافع المشروع وتعظيمها واستدامتها، وهي المؤشر الأساسي لقياس ما إذا كان المشروع يقدم القيمة التجارية المتوقعة. وتشمل المنافع المستهدفة والمواءمة الاستراتيجية والأطر الزمنية لتحقيق المنافع ومالكيها والمقاييس اللازمة لتتبع النجاح. ورغم أهمية الميزانية والجدول الزمني في الخيار B والالتزام بخطة إدارة المشروع في الخيار D لضبط المشروع، فإنها لا تؤكد مباشرةً تقديم القيمة التجارية المنشودة؛ فخطة إدارة المنافع وحدها تتتبع صراحةً تحقيق تلك الأهداف القائمة على القيمة.","الخيارات الأخرى غير صحيحة:","A. رضا أصحاب المصلحة مقياس نوعي، ولا يضمن بالضرورة تقديم المشروع للقيمة التجارية الموضوعية أو المنافع المحددة في دراسة الجدوى التجارية.","B. يشير الالتزام بالجدول الزمني والإنفاق بأقل من الميزانية إلى أداء جيد وفق القيود الداخلية للمشروع، لكنه لا يؤكد إنتاج النتائج أو المنافع التجارية المنشودة.","D. تركز خطة إدارة المشروع على «كيفية» تنفيذ المشروع، بما في ذلك النطاق والجدول الزمني والميزانية وغيرها. ورغم أهميتها، فإنها أداة إدارية، بينما خطة إدارة المنافع وثيقة أعمال صُممت تحديداً لتتبع تقديم القيمة للمنظمة وضمانه."]},"option-0":{"sourceHash":"4194ad39e9011598c5eb32d3db09784a30322c21e1aa574379150394bdbdbea8","ar":["رضا أصحاب المصلحة عن الحالة الراهنة"]},"option-1":{"sourceHash":"be02a2035cd5b0ca8b5bcefa2da79d70dbbcfafd5af03c9b2eb57343d3422336","ar":["أن المشروع أقل من الميزانية وملتزم بالجدول الزمني"]},"option-2":{"sourceHash":"dfd378e7771db837cc2cf21f7f1f8690e37bf895c542ee4ac21d90c02bba0aaa","ar":["توافق المشروع مع خطة إدارة المنافع"]},"option-3":{"sourceHash":"f5c52f0e6bf4529956fbf93404010dab94b66b7684da4afefc0894e9f3509198","ar":["توافق المشروع مع خطة إدارة المشروع"]}}},{"id":"vce-1-16","promptHash":"0eff9894f194eef4cc4ca9939443d53b996860c85bf31de2d50ca07ade9e8c3a","fields":{"prompt":{"sourceHash":"0eff9894f194eef4cc4ca9939443d53b996860c85bf31de2d50ca07ade9e8c3a","ar":["حصل مدير مشروع على معلومات من السوق من شأنها تقليل القيمة التجارية التي يقدمها مشروع جارٍ. وبناءً على هذه المعلومات، يعتقد مدير المشروع أن المشروع ينبغي إيقافه. كيف ينبغي له التعامل مع الموقف؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"36432ea08ca387d46bd70901fe4e1125b149c0987a09ab6f06afff9217733c77","ar":["B. مناقشة الراعي والتوصية بإعادة تقييم القيمة التجارية للمشروع.","تتمثل مسؤولية مدير المشروع في الحفاظ على توافق المشروع مع أهداف المنظمة ودراسة الجدوى التجارية. وبما أن راعي المشروع هو مالك الدراسة والداعم لها، ينبغي لمدير المشروع عرض معلومات السوق الجديدة عليه، وتقديم تحليل مهني، والتوصية بإعادة تقييم القيمة التجارية للمشروع. ويتيح هذا النهج التعاوني للراعي اتخاذ قرار مستنير بشأن مستقبل المشروع، لأنه يتحمل المساءلة النهائية عن الاستثمار.","الخيارات الأخرى غير صحيحة:","A. لا يملك مدير المشروع صلاحية إلغاء المشروع من جانب واحد. فهذا القرار يعود إلى راعي المشروع أو جهة الحوكمة، بناءً على تقييم دراسة الجدوى التجارية.","C. تجاهل معلومات السوق الجديدة والاستمرار في النطاق الأصلي، أي «العمل كالمعتاد»، يتجاهل الواجب المهني بتنبيه الراعي إلى المخاطر المؤثرة في القيمة التجارية. ولا تكفي مراجعة مصفوفة المخاطر إذا لم يعد المبرر الاستراتيجي الأساسي للمشروع صالحاً.","D. تعديل قائمة الأعمال أو نطاق المشروع استجابةً لتحولات السوق الخارجية قبل التشاور مع الراعي أو إعادة التحقق من دراسة الجدوى التجارية يتجاوز صلاحيات مدير المشروع، وقد يؤدي إلى عدم التوافق مع الأهداف الاستراتيجية."]},"option-0":{"sourceHash":"4e8a3bea7ae13626380d5d74e27910c623720248252a7fb959ca008b09a7649c","ar":["مناقشة راعي المشروع وإلغاء المشروع."]},"option-1":{"sourceHash":"5106affa00cb29aa99a1d8dd1846834839bf1ebf36f646ac9101ce563dc40a43","ar":["مناقشة الراعي والتوصية بإعادة تقييم القيمة التجارية للمشروع."]},"option-2":{"sourceHash":"f095199dec63341ec1deedc43530c88147b1ab29388c1e7b1f9bf9cf7c3e1146","ar":["مواصلة العمل ضمن النطاق المحدد ومراجعة مصفوفة المخاطر."]},"option-3":{"sourceHash":"90338fb72056122258ce609078f080446cc4bf5596f6728f3a7211f06657ea02","ar":["حذف البنود التي لم تعد منطبقة من قائمة الأعمال وعرض القائمة على فريق المشروع."]}}},{"id":"vce-1-17","promptHash":"e78dff90fb905601c1f0330fb0705a5cfd2951386571e94ef163b8b757f324c7","fields":{"prompt":{"sourceHash":"e78dff90fb905601c1f0330fb0705a5cfd2951386571e94ef163b8b757f324c7","ar":["في بيئة مصفوفية ضعيفة، يتأخر عضوان أساسيان في الفريق عن إنجاز مهامهما، مما سيؤثر في نجاح المشروع.","وبعد مزيد من التقصي، يكتشف مدير المشروع وجود خلافات غير محلولة بينهما. ويطلب منهما إيجاد طريقة لحلها، لكن المحاولة تفشل. ثم يجتمع بهما للوصول إلى حل دائم لهذه الخلافات، وتفشل هذه المحاولة أيضاً.","ماذا ينبغي لمدير المشروع فعله بعد ذلك؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"75c3a8550778cd656dca73997450b887aa3e11e2aa3dd6431f68088f2746ce56","ar":["C. تصعيد المسألة إلى سلطة أعلى","في المنظمة المصفوفية الضعيفة، يتمتع مدير المشروع بسلطة رسمية محدودة على الموارد. وعندما يفشل التدخل المباشر والوساطة في حل نزاع حرج يعرّض نجاح المشروع للخطر فعلياً، يجب عليه استخدام خطوط التبعية الإدارية. ويكون التصعيد إلى سلطة أعلى، عادةً المديرين الوظيفيين المسيطرين مباشرةً على هذه الموارد أو راعي المشروع، الخطوة التالية اللازمة للحصول على الدعم المطلوب لحل النزاع بين الموظفين.","الخيارات الأخرى غير صحيحة:","A. يفتقر مدير المشروع في المنظمة المصفوفية الضعيفة عادةً إلى الصلاحية الرسمية لإيقاف الموظفين عن العمل من جانب واحد.","B. مناقشة الخلافات الشخصية أمام الفريق بأكمله تصرف غير مهني وذو نتائج عكسية، ومن المرجح أن يزيد النزاع سوءاً ويضر بالروح المعنوية العامة للفريق.","D. إعادة تكليف أعضاء الفريق قرار يتعلق بإدارة الموارد، ويقع عموماً ضمن اختصاص المدير الوظيفي في الهيكل المصفوفي الضعيف. وينبغي لمدير المشروع طلب مساعدته عن طريق التصعيد، بدلاً من محاولة إعادة توزيع الموارد بصورة مستقلة."]},"option-0":{"sourceHash":"281d882a154dd472d4122351b19e9e5ac9c00edd1518afdc2acfbf2fc312d4a1","ar":["إيقاف العضوين الأساسيين عن العمل فوراً."]},"option-1":{"sourceHash":"f42d89b613dc08eccaaad1d733a75ef5105c393d22f615e95d47e5626bb05cc7","ar":["إدراج المسألة على جدول أعمال اجتماع الفريق التالي"]},"option-2":{"sourceHash":"7e533396304d86c4632a562a9cfe289ad4ee6e8a99110f2407bfbca888eb9c3d","ar":["تصعيد المسألة إلى سلطة أعلى"]},"option-3":{"sourceHash":"4fe98af2d6f520aebdec3fb8c4335b73bcbcd931ad7cc214f03c80d8fdb8bdfb","ar":["إعادة تكليف أحد العضوين الأساسيين بمهمة مختلفة"]}}},{"id":"vce-1-18","promptHash":"9efe241f9e797436cc231e775347f622715c4d62c736c1a9340bcba86c2c0f61","fields":{"prompt":{"sourceHash":"9efe241f9e797436cc231e775347f622715c4d62c736c1a9340bcba86c2c0f61","ar":["أنت مدير مشروع إنشائي. ماذا ينبغي لك فعله لضمان تسليم المشروع بنجاح؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"26df1bceff6a356bfbb9c4c0f1d89e67d715878525309cb595a29500da48a318","ar":["D. تحديد مخاطر المشروع ومعايير النجاح اللازمة.","تحديد معايير النجاح والمخاطر خطوة أساسية في إدارة المشاريع. فمعايير النجاح توفر نتائج قابلة للقياس تحدد ما إذا كان المشروع قد حقق أهدافه، بينما يتيح تحديد المخاطر لمدير المشروع تطوير استراتيجيات استباقية للتخفيف من المشكلات المحتملة. وبدون هذين العنصرين، يفتقر المشروع إلى هدف محدد وخطة للتعامل مع عدم اليقين، وكلاهما ضروري للتسليم الناجح في أي مشروع، وخصوصاً المشاريع الإنشائية.","الخيارات الأخرى غير صحيحة:","A. رغم أن الاحتياطيات الإدارية جزء من إدارة التكلفة، فإن مجرد إنشاء احتياطي لا يكفي لضمان النجاح. ويجب أولاً تحديد المخاطر التي تستلزم مثل هذا الاحتياطي.","B. بناء الفريق أسلوب مفيد لتطويره، لكنه ليس الإجراء الأساسي المطلوب لضمان تحقيق أهداف المشروع.","C. رغم أهمية التواصل مع أصحاب المصلحة بشأن التأخيرات ضمن إدارة الاتصالات، فإنه إجراء تفاعلي يُتخذ عند حدوث التأخير، وليس خطوة استباقية لضمان التسليم الناجح."]},"option-0":{"sourceHash":"4c04850ac0127ab73800299c99b36fecb92962aa3f50ab3515dd44845df1a4a2","ar":["إنشاء احتياطي إداري للتعامل مع المخاطر غير المعروفة عند وقوعها"]},"option-1":{"sourceHash":"5c5ba42777bc5a661b9a0bfc874bc8c00af24bb966ca1e9025ef93cb5b63f6ac","ar":["تنفيذ نشاط لبناء الفريق"]},"option-2":{"sourceHash":"c2b31343af28a62e9077ef5112d0a6438eef8f779c6fd688f9c9969933b8105f","ar":["الاجتماع بأصحاب المصلحة لإبلاغهم بتأثير تأخر المشروع في الجدول الزمني والميزانية والتكلفة."]},"option-3":{"sourceHash":"11e6020bd517ef4546d85a0f9ce780f7fa29980868b2a8799005d8a52d4a06df","ar":["تحديد مخاطر المشروع ومعايير النجاح اللازمة."]}}},{"id":"vce-1-19","promptHash":"af8ba99e9fbcb4e2eb06a851e5b4c2f388fb53d05e327319a3d3dcb80d2673a0","fields":{"prompt":{"sourceHash":"af8ba99e9fbcb4e2eb06a851e5b4c2f388fb53d05e327319a3d3dcb80d2673a0","ar":["وصل مشروع متعدد المراحل، نُفِّذ بموارد داخلية، إلى بوابة مرحلة. ويريد أصحاب المصلحة الرئيسيون تحديد ما إذا كانت المرحلة قد استوفت معايير نجاحها، وما إذا كان ينبغي للمشروع الانتقال إلى المرحلة التالية. بالإضافة إلى خطة إدارة المشروع، ما الوثائق المطلوبة؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"119c1105d98f8b92c6a1a123a9d69781f5944a9ed5d3761cd7724e4ed236c76f","ar":["D. وثائق الأعمال وميثاق المشروع","عند بوابة المرحلة، أو نقطة الإيقاف، يجب على أصحاب المصلحة تقييم استمرار توافق المشروع مع مقصده الاستراتيجي الأصلي واستمراره في تقديم القيمة المتوقعة. ويتضمن ميثاق المشروع رسمياً معايير نجاحه وأهدافه عالية المستوى. وتوفر وثائق الأعمال، وتحديداً دراسة الجدوى التجارية وخطة إدارة المنافع، مبرر وجود المشروع وتحليل التكلفة والمنفعة وإطار قياس تحقق القيمة المنشودة. وتضمن مراجعتها أن المشروع لا يستوفي المتطلبات الفنية فحسب، بل لا يزال يحقق أهدافه التجارية قبل المضي قدماً.","الخيارات الأخرى غير صحيحة:","A. رغم أن مستودع الدروس المستفادة من أصول العمليات التنظيمية (OPA) القيّمة للتحسين المستقبلي، فإنه ليس الوثيقة الأساسية لتبرير الاستمرار الاستراتيجي للمشروع عند بوابة المرحلة.","B. سجل المخاطر وتقرير المخاطر ضروريان لإدارة عدم اليقين، لكنهما يركزان على تهديدات تنفيذ المشروع، لا على معايير اتخاذ القرار الاستراتيجي للتصريح بالانتقال إلى المرحلة التالية.","C. الاتفاقيات وعقود المشتريات لازمة لإدارة الموردين الخارجيين، لكنها ليست الوثائق المستخدمة لتقييم النجاح الاستراتيجي العام أو مبرر استمرار المشروع."]},"option-0":{"sourceHash":"6f30807aedc1a3130d3f5d6dcb18b311ed341e06fc155891b5ab05cc1da9f86e","ar":["سجل الدروس المستفادة ومستودع الدروس المستفادة"]},"option-1":{"sourceHash":"52fe36f8adeefb4ed414e3e582c81b07841054be3fb15a7bca82d50a1ad35b79","ar":["سجل المخاطر وتقرير المخاطر"]},"option-2":{"sourceHash":"f9b9398b0fd459188ffc5699cfff83dfedbf241c50170eb6736fcae240ba0a85","ar":["الاتفاقيات، بما فيها عقود المشتريات"]},"option-3":{"sourceHash":"d6bd94653a09c41570aa3daa70a647add79184bc135171be983a7fd801cfc75b","ar":["وثائق الأعمال وميثاق المشروع"]}}},{"id":"vce-1-20","promptHash":"8a26471c92385167d76f83481a713be217129829c1b8f0f086713fa306af6a07","fields":{"prompt":{"sourceHash":"8a26471c92385167d76f83481a713be217129829c1b8f0f086713fa306af6a07","ar":["طُلب من مدير مشروع المساهمة في وثيقة تصف ما يُراد تحقيقه من المشروع بعد اكتماله بنجاح، وكيفية قياس ذلك. ما الاسم المحتمل لهذه الوثيقة؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"fca6dee06f90d8655760697f446346cc7cc423d39c7e0be3083bb487c599e64a","ar":["D. خطة إدارة المنافع","خطة إدارة المنافع هي الوثيقة التي تحدد تحديداً النتائج المنشودة، أي المنافع، والإطار الزمني لتحقيقها والمقاييس، أي كيفية قياسها، لضمان تقديم المشروع للقيمة المتوقعة للمنظمة الراعية. وهي تربط بين تسليمات المشروع ونجاح المنظمة.","الخيارات الأخرى غير صحيحة:","A. تصف خطة إدارة التغيير كيفية إدارة تغييرات نطاق المشروع أو جدوله الزمني أو ميزانيته وضبطها؛ ولا تحدد المنافع التجارية للمشروع المكتمل.","B. تصف خطة إدارة المشروع كيفية تنفيذه ومراقبته وضبطه؛ وهي دليل شامل لإدارة العمل، لكنها ليست الوثيقة الأساسية لتعريف المنافع التجارية طويلة الأجل وقياسها.","C. بيان العمل (SOW) وثيقة تصف المنتجات أو الخدمات أو النتائج التي سيقدمها المشروع. ويركز على نطاق التسليمات، لا المنافع التجارية الاستراتيجية أو مقاييس قياسها بعد انتهاء المشروع."]},"option-0":{"sourceHash":"2d07821c965ad79d20c70c20e1382d608618c9d9fa393f9c355f5ac17c13f9cf","ar":["خطة إدارة التغيير"]},"option-1":{"sourceHash":"a7bc5d2baca450b97404428de3bb8a352ce46410c04e001394a6b8416f183f5d","ar":["خطة إدارة المشروع"]},"option-2":{"sourceHash":"0ed71611c6960cbd77d50f0f04b152df3f95b96983311ac3e8c63ffa6b519ccc","ar":["بيان العمل"]},"option-3":{"sourceHash":"55922b653a9fa6b861aedbc4b83344dbacc041bc1ab2afe5c8ade0d54b726955","ar":["خطة إدارة المنافع"]}}},{"id":"vce-1-21","promptHash":"9ace2a636f1d8fce98dd73d882a4e121f4ede895b63ea1ee4aa768627d5794ee","fields":{"prompt":{"sourceHash":"9ace2a636f1d8fce98dd73d882a4e121f4ede895b63ea1ee4aa768627d5794ee","ar":["أيٌّ من الأساليب التالية يمكن أن يضمن إشراك أصحاب المصلحة في مراحل المشروع المناسبة والحصول على التزامهم المستمر بنجاح المشروع أو تأكيده؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"57c4a6b35ac14603ea7b0d111c976884f10922571a6fb8c41ef442155e0b0851","ar":["A. اجتماعات بوابات المراحل","اجتماعات بوابات المراحل، المعروفة أيضاً ببوابات المرحلة أو مراجعات المراحل أو نقاط الإيقاف، هي نقاط تحقق حاسمة للحوكمة. وتوفر فرصة رسمية لأصحاب المصلحة الرئيسيين لمراجعة تقدم المشروع وتقييم الأداء قياساً بالأهداف وتقييم خطة المرحلة التالية. ويضمن هذا الإشراك استمرار توافقهم مع اتجاه المشروع، ويؤكد التزامهم المستمر قبل استثمار موارد إضافية.","الخيارات الأخرى غير صحيحة:","B. تُستخدم عمليات تدقيق الأداء بصفة أساسية لتحديد مدى التزام أنشطة المشروع بسياسات المنظمة والمشروع وعملياتهما وإجراءاتهما. ورغم أنها توفر بيانات، فإن غرضها الأساسي ليس الإشراك المستمر لأصحاب المصلحة أو إدارة التزامهم.","C. وضع القواعد الأساسية نشاط على مستوى الفريق لتحديد السلوك والمعايير المتوقعة من فريق المشروع. وهو أسلوب داخلي لإدارة الفريق، وليس استراتيجية لإشراك أصحاب المصلحة.","D. إدارة فريق المشروع نشاط تشغيلي مستمر يركز على أداء الفريق وتطويره وتحفيزه. وهو، كالقواعد الأساسية، نشاط داخلي للفريق، وليس آلية أساسية لإشراك أصحاب المصلحة على المستوى الرفيع أو تأكيد التزامهم."]},"option-0":{"sourceHash":"be2af3c594794465e8d410fdf2d3bda7fc94a99c8a45007f0bcd31e0ea7dc89e","ar":["اجتماعات بوابات المراحل"]},"option-1":{"sourceHash":"188723ecaed9ca71cbd08c01cddba272ceae372575aea4bf1c3c348a18590cdb","ar":["عمليات تدقيق الأداء"]},"option-2":{"sourceHash":"8704ca3a77500a1fac634255327819003dfd096266098e6e7edb150e0b0aae3a","ar":["وضع القواعد الأساسية"]},"option-3":{"sourceHash":"630283f866eff6c3066995995847752d387068f5b10b4d9ee2513f95df9b1254","ar":["إدارة فريق المشروع"]}}},{"id":"vce-1-22","promptHash":"1b78b43559035a3d94cc6697b530e6115c42c055860c0d2ca3b4e357224b6f7c","fields":{"prompt":{"sourceHash":"1b78b43559035a3d94cc6697b530e6115c42c055860c0d2ca3b4e357224b6f7c","ar":["أنت مدير مشروع HDM. يجب إتمام المشروع بحلول 11 سبتمبر، ولا يجوز أن تتجاوز تكلفته ⁦$10,000⁩. يُعد مبلغ ⁦$10,000⁩ مثالاً على أيٍّ مما يلي؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"63255b617ee219431c2a44fbf7b7f6969785c7fec7b5329f6afd2a28c2d6e8d4","ar":["B. قيد","في إدارة المشاريع، القيد عامل يحد من تنفيذ المشروع. وتشمل القيود الشائعة الجدول الزمني، أي وجوب الانتهاء في تاريخ محدد، والميزانية، أي عدم تجاوز مبلغ محدد، والنطاق، أي العمل المحدد الواجب تسليمه. وغالباً ما تُسمّى «القيود الثلاثية» أو مثلث قيود المشروع. وبما أن المشروع يخضع لحد صارم للتمويل المتاح، فإن مبلغ ⁦$10,000⁩ مثال واضح على قيد متعلق بالتكلفة.","الخيارات الأخرى غير صحيحة:","A. تاريخ الإنجاز المجدول نوع محدد من القيود المتعلقة بالوقت، أي قيد على الجدول الزمني، لكن السؤال يسأل تحديداً عن مبلغ ⁦$10,000⁩ المرتبط بالتكلفة.","C. الافتراض عامل يُعد صحيحاً أو واقعياً أو مؤكداً لأغراض التخطيط، دون إثبات أو برهان. وحد الميزانية البالغ ⁦$10,000⁩ متطلب أو حد، أي قيد، وليس افتراضاً.","D. الاحتياطي الإداري مبلغ محدد من ميزانية المشروع يُحتفَظ به لأغراض الرقابة الإدارية على الأعمال غير المتوقعة التي تقع ضمن نطاق المشروع. وهو ليس الحد الإجمالي للميزانية نفسها."]},"option-0":{"sourceHash":"62aaf63f9f5ba879c816fbf2bfbb32e03c3c00cd3b31bc63bc67362bf90cd3e4","ar":["تاريخ الإنجاز المجدول"]},"option-1":{"sourceHash":"aa78ff00c461100dc99a26132ca9ddc013921316ecae4a7ff4ca92fb266e83a4","ar":["قيد"]},"option-2":{"sourceHash":"cf88cbd2d3ab5865591a0596319a5300a45374fe2d74c9cde2f00f58169224b1","ar":["افتراض"]},"option-3":{"sourceHash":"7d5e4d3fe61dd5e7d7462b8a809d74d597810eca9753e9d3edcb7bdf942542e8","ar":["احتياطي إداري"]}}},{"id":"vce-1-23","promptHash":"328d5a985f2d9ce32dd782e28b8cca6786898f5ac6ea06c18702951c7a4b9c59","fields":{"prompt":{"sourceHash":"328d5a985f2d9ce32dd782e28b8cca6786898f5ac6ea06c18702951c7a4b9c59","ar":["أخبرك أعضاء فريقك بأنهم مثقلون بمهام كثيرة. ويقولون إن لديهم تكليفات عديدة إلى جانب المهام الأساسية في المشروع. وقد وعدتهم بإزالة هذا العبء الزائد من المهام. أنت مدير مشروع في:"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"ef259f0a18a59b3fd32e9d4d75b12d9832e5756fa827611ca1e9ebfabb8d24f1","ar":["B. منظمة ذات هيكل مصفوفي قوي","في المنظمة ذات الهيكل المصفوفي القوي، يتمتع مدير المشروع بدرجة عالية من السلطة، غالباً أعلى من سلطة المدير الوظيفي، على موارد المشروع وأولوياته. وامتلاكه الصلاحية الرسمية لإزالة المهام المتنافسة مع عمل المشروع أو إعادة توزيعها يدل على تأثير قوي في عبء عمل الفريق. وعادةً ما يتبع أعضاء الفريق في الهيكل المصفوفي جهتين، وينجزون مهام لمديرهم الوظيفي ولمدير المشروع، مما يفسر وجود «مهام كثيرة إلى جانب المهام الأساسية في المشروع».","الخيارات الأخرى غير صحيحة:","A. في المصفوفة المتوازنة، تتوزع السلطة بصورة أكثر تساوياً بين المدير الوظيفي ومدير المشروع. ورغم امتلاك مدير المشروع بعض التأثير، فإنه قد لا يمتلك الهيمنة اللازمة لإلغاء المهام المسندة من الإدارات الوظيفية من جانب واحد.","C. في المنظمة القائمة على المشاريع، يتبع أعضاء الفريق مدير المشروع بصفة أساسية أو حصرية، ولا تكون لديهم عموماً «مهام كثيرة إلى جانب المهام الأساسية في المشروع»، لأن أعمالهم مخصصة لذلك المشروع.","D. في المصفوفة الضعيفة، تكون سلطة مدير المشروع محدودة جداً، ويعمل أكثر بوصفه منسقاً أو ميسّر متابعة. وعادةً ما يفتقر إلى القدرة على تجاوز تكليفات المدير الوظيفي لتخفيف عبء عمل الفريق."]},"option-0":{"sourceHash":"64be61c8082820049f73efc40d0db56a324546b021e3432ac2b026a0e8d09abb","ar":["منظمة ذات هيكل مصفوفي متوازن"]},"option-1":{"sourceHash":"851a5174dcc5166aaf5236f760be2fbaf7539489e7fb299399baa7723724c775","ar":["منظمة ذات هيكل مصفوفي قوي"]},"option-2":{"sourceHash":"caa19d4eb1dd6cf14bc963a4b15ff48a2912f9dcb8f48cc662bbcf40dc2d599c","ar":["منظمة قائمة على المشاريع"]},"option-3":{"sourceHash":"529cdf81b909de62617c7c62e32d500e3093c2058edbef4c856acb50a3513f62","ar":["منظمة ذات هيكل مصفوفي ضعيف"]}}},{"id":"vce-1-24","promptHash":"7402b96cd9fc8691ef4e7c1d98f6dac3d1fc993a50ebd8a11a4f54eb9d06a1e4","fields":{"prompt":{"sourceHash":"7402b96cd9fc8691ef4e7c1d98f6dac3d1fc993a50ebd8a11a4f54eb9d06a1e4","ar":["بعد اجتماع للإدارة العليا، يطلب المدير الذي ترأس الاجتماع من مدير المشروع توثيق بنود العمل وإبلاغها لجميع أصحاب المصلحة. ينتمي مدير المشروع إلى منظمة ذات ______________."]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"dd8a69003dfd66b23fba64e3bf26b70c8ea9b381528e7c93db3244c3d2711c82","ar":["A. مصفوفة ضعيفة","في المنظمة المصفوفية الضعيفة، يتمتع مدير المشروع بسلطة محدودة جداً. وغالباً ما يعمل منسق مشروع أو ميسّر متابعة للمشروع (Project Expeditor). وفي دور ميسّر المتابعة، تكون مهمته الأساسية العمل مساعداً إدارياً وحلقة وصل للاتصالات، مع ضمان توثيق المعلومات ونشرها. ولأنه يفتقر إلى صلاحية اتخاذ القرارات أو فرضها، يعتمد على الإدارة لتحديد التوجه، وتتمثل مساهمته الأساسية في تنسيق تدفق المعلومات بين أصحاب المصلحة.","الخيارات الأخرى غير صحيحة:","B. في المصفوفة المتوازنة، يتمتع مدير المشروع بسلطة متوسطة. وعادةً ما يشارك في اتخاذ القرارات والتفاوض على الموارد بدرجة تتجاوز مجرد التنسيق الإداري للاتصالات.","C. في المصفوفة القوية، يتمتع مدير المشروع بسلطة واسعة، ويتحمل مسؤولية قيادة المشروع وتحديد العمل وضبط ميزانيته، بدلاً من العمل مجرد ميسّر متابعة.","D. تجميع الفريق في موقع واحد (Tight Matrix) ليس نوعاً رسمياً من الهياكل التنظيمية بالمعنى نفسه؛ بل يشير إلى وضع أعضاء فريق المشروع فعلياً في مكان واحد لتعزيز التواصل والتعاون."]},"option-0":{"sourceHash":"da3f2ebe858ab4a2a5f99b43d201061d4f61b7db055aad903f12612dd272d1cb","ar":["مصفوفة ضعيفة"]},"option-1":{"sourceHash":"8b2c84f22ea262d7867dba0746493ae42557c9896df3596c0d7c47d9a74d08b6","ar":["مصفوفة متوازنة"]},"option-2":{"sourceHash":"736e6de65e07d3663857c4c480ba7407a375b43c32c5631ea39ea0c7e15ab636","ar":["مصفوفة قوية"]},"option-3":{"sourceHash":"eda5e0a8f63863fc9eebcb63ca4299deb5f66fb3ab6bf56529760a78d9e9a20c","ar":["تجميع الفريق في موقع واحد (Tight Matrix)"]}}},{"id":"vce-1-25","promptHash":"e3abe06c945f80e8f3c3c23ac8a712fa95b5878b64f52c74d9e79645a17952e2","fields":{"prompt":{"sourceHash":"e3abe06c945f80e8f3c3c23ac8a712fa95b5878b64f52c74d9e79645a17952e2","ar":["تواجه باستمرار صعوبة في توفير الموارد لمشروعك لأنها مشتركة بين مشاريع متعددة. إلى من ينبغي تصعيد هذه المسألة؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"49679f7531157cfc7c3ec74826f5384d8db0cdd799e7a277312a72f0647b5318","ar":["C. مكتب إدارة المشاريع في المنظمة (PMO)","في معظم الهياكل التنظيمية، وخصوصاً حين تكون الموارد مشتركة عبر محفظة مشاريع، يكون مكتب إدارة المشاريع (PMO) الجهة المسؤولة عن حوكمة الموارد وإدارتها وحل النزاعات المتعلقة بتخصيصها. ويحتفظ بالإشراف اللازم لترتيب أولويات الاحتياجات من الموارد على مستوى المنظمة، ويمكنه حل التنافس بين المشاريع.","الخيارات الأخرى غير صحيحة:","A. تدير الموارد البشرية السياسات العامة للموظفين والتعيين والرواتب، لكنها لا تشارك عادةً في القرارات التشغيلية اليومية لتخصيص موارد المشاريع أو حل النزاعات على الموارد بين المشاريع.","B. يتحمل الراعي مسؤولية نجاح المشروع ودعمه على المستوى الرفيع، لكنه قد لا يمتلك الرؤية الشاملة للمنظمة اللازمة لإدارة النزاعات على الموارد بين مشاريع متعددة. ويُعد مكتب إدارة المشاريع جهة التصعيد المعتادة لقيود الموارد المشتركة بين المشاريع.","D. مدير المشتريات مسؤول عن اقتناء السلع والخدمات الخارجية من الموردين والمقاولين، لا عن إدارة الموظفين الداخليين المشتركين بين المشاريع الداخلية أو توزيعهم."]},"option-0":{"sourceHash":"32d36ac9fe267f98c888fb5a01955935d299f80e44418426d3a45834fc7b1dd7","ar":["إدارة الموارد البشرية"]},"option-1":{"sourceHash":"219fab952223f4af9d92d74591e0233715279279cdd2ff2e5810e1224e87d3e8","ar":["راعي المشروع"]},"option-2":{"sourceHash":"91ca1c8e24ba0ba35d8b9cfec4c26d98ab6f94255534c8385082c13dbbda8319","ar":["مكتب إدارة المشاريع في المنظمة (PMO)"]},"option-3":{"sourceHash":"1ef5b4f6fab5cf90d00eb02650b8bbf28bb6dcf9bc8b325a8fabb728996a9aa6","ar":["مدير المشتريات"]}}},{"id":"vce-1-26","promptHash":"87aa6613b239c0f0e79ed915e787d8a8bdbaacc5cd28a794bce370ca33c1379e","fields":{"prompt":{"sourceHash":"87aa6613b239c0f0e79ed915e787d8a8bdbaacc5cd28a794bce370ca33c1379e","ar":["يرى بعض زملائك في إدارة المشاريع أن القيادة ومهارات استخدام برامج إدارة المشاريع من المهارات المهمة التي ينبغي لمدير المشروع امتلاكها. وفقاً لمثلث المواهب لدى معهد إدارة المشاريع (PMI Talent Triangle)، أيٌّ مما يلي يعكس جميع مجالات كفاءة مدير المشروع؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"2c19fc81fbab25437fe78067bf61e09ede18d01bf9d5a211bcfecbd89771d715","ar":["D. طرق العمل، والمهارات المؤثرة، والفطنة التجارية","مثلث المواهب لدى PMI إطار يحدد مجموعات المهارات الأساسية لمحترفي إدارة المشاريع في بيئة العمل الحديثة. ويتكون من المجالات الرئيسية الثلاثة التالية:","طرق العمل (Ways of Working): كانت تُسمّى سابقاً «إدارة المشاريع التقنية». وتركز على أساليب التسليم المختلفة، مثل النهج الرشيق (Agile)، والنهج الشلالي (Waterfall)، والتفكير التصميمي، ونهج تقليل الهدر (Lean)، بما يتيح لمديري المشاريع تكييف نهجهم مع احتياجات المشروع المحددة.","المهارات المؤثرة (Power Skills): كانت تُسمّى سابقاً «القيادة». وتشمل مهارات التعامل مع الآخرين، مثل التواصل والتعاطف وبناء الفريق والقيادة والذكاء العاطفي، وهي ضرورية للتأثير في الفرق وأصحاب المصلحة وتحفيزهم.","الفطنة التجارية (Business Acumen): كانت تُسمّى سابقاً «الإدارة الاستراتيجية وإدارة الأعمال». وتركز على فهم السياق التنظيمي وبيئة الأعمال والمعرفة الخاصة بالقطاع والمواءمة الاستراتيجية اللازمة لضمان تقديم المشروع قيمة حقيقية للمنظمة.","الخيارات الأخرى غير صحيحة:","تصف الخيارات A وB وC جوانب مختلفة من الخبرة في المشاريع أو السمات الإدارية العامة، لكنها لا تتوافق مع المسميات الحالية لمثلث المواهب لدى PMI."]},"option-0":{"sourceHash":"21eec822f8841bfe878b75d088e8e950b26e73f3c7ae485e7b53496ca6d87a38","ar":["الخبرة الإدارية، والخبرة في العمليات، والخبرة في المجال"]},"option-1":{"sourceHash":"2b15d5949ddac05a78781f9f132f956b420d495bbce036a7d56185761cc506f0","ar":["إدارة المشاريع، وإدارة الأفراد، والأعمال والاستراتيجية"]},"option-2":{"sourceHash":"593496446b2a3de79147593323f9c1fdfa599e08d402c66871cd05f7ed02ef1d","ar":["المعرفة، والأداء، والشخصية"]},"option-3":{"sourceHash":"1a6a37cff3c78997bd9249578f80cdace1a953901e8fe055488affa68f854942","ar":["طرق العمل (Ways of Working)، والمهارات المؤثرة (Power Skills)، والفطنة التجارية (Business Acumen)"]}}},{"id":"vce-1-27","promptHash":"cfcea08dd8c765def01be18c1a39015d751ba2367a4bd3835640421b77e0d463","fields":{"prompt":{"sourceHash":"cfcea08dd8c765def01be18c1a39015d751ba2367a4bd3835640421b77e0d463","ar":["يطلب مكتب إدارة المشاريع في منظمتك دورياً مُنتَجات العمل ووثائق المشاريع من جميع المشاريع، ويتحقق من الالتزام بالمعايير المؤسسية لإدارة المشاريع من عدمه. كما يقدم الدعم بتوفير القوالب والإرشادات المتعلقة بإدارة المشاريع عند الطلب. إلى أي نوع من مكاتب إدارة المشاريع يشير ذلك؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"2209dd768b5fbce5d40318cc279ea943fad1c93d94588a44133f507bc85d2191","ar":["D. مكتب إدارة مشاريع رقابي","يتميز مكتب إدارة المشاريع الرقابي بتقديم الدعم والتوجيه، وكذلك، والأهم، باشتراط الامتثال. فعند فحص وثائق المشاريع ومُنتَجات عملها دورياً وتدقيق الالتزام بالمعايير المؤسسية، يمارس المكتب الإشراف والإلزام. ورغم تقديمه الدعم، مثل القوالب والإرشادات، فإن المراقبة الفعلية للامتثال تميزه عن المكتب الداعم فقط.","الخيارات الأخرى غير صحيحة:","A. المكتب الحوكمي ليس فئة معيارية وفق تعريف PMBOK؛ فرغم ممارسة المكاتب للحوكمة، فإن التصنيفات المحددة هي: داعم، ورقابي، وتوجيهي.","B. يتولى مكتب إدارة المشاريع التوجيهي السيطرة الكاملة على المشاريع بإدارتها مباشرةً. وفي هذا النوع، يتبع مديرو المشاريع المكتب مباشرةً، ويتمتع المكتب بالسلطة الكاملة على تنفيذ المشاريع.","C. يؤدي المكتب الداعم دوراً استشارياً، فيوفر القوالب وأفضل الممارسات والتدريب وإمكانية الوصول إلى المعلومات والدروس المستفادة. وتكون درجة سيطرته منخفضة، ولا يجري عادةً عمليات تدقيق أو يفرض الامتثال للمعايير."]},"option-0":{"sourceHash":"8dcf101e711e8f48ab7dc1b43bea4f52f6195bcc4cfa155d624467f81cb8bcdb","ar":["مكتب إدارة مشاريع حوكمي"]},"option-1":{"sourceHash":"07e4591dbcf19e8c04e787c28f5418c93eb5773fcd7dd6c6117c90380f33a9f2","ar":["مكتب إدارة مشاريع توجيهي"]},"option-2":{"sourceHash":"ddfc751d72219d41de10973710d5c40f53832e096c93ff00980cc16817c31b07","ar":["مكتب إدارة مشاريع داعم"]},"option-3":{"sourceHash":"f18cf780c84184ca60cd47f139fc9927cd968b8c89750858432bef07b45cf5d4","ar":["مكتب إدارة مشاريع رقابي"]}}},{"id":"vce-1-28","promptHash":"f3adae02abaab8e7556b9bc2277f12e1df2473d0525dff9d794d1ba5ba995090","fields":{"prompt":{"sourceHash":"f3adae02abaab8e7556b9bc2277f12e1df2473d0525dff9d794d1ba5ba995090","ar":["يطلب أحد العملاء تغييرات متكررة في النطاق، رغم وضع رؤية للمنتج وخريطة طريق في بداية المشروع. ما نوع دورة حياة التطوير المرجح استخدامه؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"9515018ef98d6d26236d2da7dec24667b2a1fc4f96c19ceb31c35a68b96d2fa4","ar":["B. التكيفية","صُممت دورة الحياة التكيفية، أو الرشيقة، تحديداً لاستيعاب التغيير. ورغم أن المشاريع التي تستخدم هذا النهج تضع رؤية وخريطة طريق عالية المستوى لتوفير توجه استراتيجي، فإن النطاق التفصيلي يُترَك مرناً عن قصد لتحسينه من خلال التغذية الراجعة والتكرارات المتواترة. وتعد طلبات العميل المتكررة لتغيير النطاق سمة مميزة للبيئات التكيفية، إذ يعطي الفريق الأولوية لتقديم القيمة والاستجابة بدلاً من الالتزام الصارم بالخطة الأولية.","الخيارات الأخرى غير صحيحة:","A. النهج الشلالي نهج تقليدي خطي، يُراد فيه تحديد النطاق مقدماً، وتُثبَّط التغييرات أو تُضبَط بعملية رسمية لتجنب تأثيرها في الجدول الزمني والميزانية.","C. النهج التنبؤي، الذي يُستخدم غالباً مرادفاً للشلالي، نموذج يُحدَّد فيه نطاق المشروع ووقته وتكلفته في أبكر وقت ممكن من دورة الحياة. وهو غير ملائم لسيناريو يغيّر فيه العميل النطاق باستمرار.","D. يجمع النهج الهجين بين التنبؤي والتكيفي. ورغم أن المشروع الهجين قد يسمح ببعض التغييرات، فإن البيئة التي تتميز بطلبات تغيير نطاق متكررة طوال دورة الحياة تُوصَف أساساً بأنها تكيفية."]},"option-0":{"sourceHash":"6b53bc225e0aae1d798f348e41b1801dfab38c61af69b5f657e8eae2cffd9ad1","ar":["الشلالية (Waterfall)"]},"option-1":{"sourceHash":"ceb6931ea57cc99912b7ece16f363cc3b42db89fd015d9937d7bb42997dcb663","ar":["التكيفية"]},"option-2":{"sourceHash":"666681affe05a8062084fdf30fdaae0d419aaeab57b016e98770385f0ff53c40","ar":["التنبؤية"]},"option-3":{"sourceHash":"6c67dc13f83949fe089ca86225b136b5f40ac5268ebf92fbefe45f1f94e8064b","ar":["الهجينة"]}}},{"id":"vce-1-29","promptHash":"b005adcedf18445a114e0855c68901fcf108edc844d1cd32862100cc9016622f","fields":{"prompt":{"sourceHash":"b005adcedf18445a114e0855c68901fcf108edc844d1cd32862100cc9016622f","ar":["ماذا تُسمّى مجموعة المشاريع المترابطة التي تُدار بصورة منسقة للحصول على منافع؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"57212de14104fdaab20cd57c3ad51960a1d88c09b1ac258708eefb35c471752d","ar":["A. برنامج","يُعرَّف البرنامج بأنه مجموعة من المشاريع المترابطة والبرامج الفرعية وأنشطة البرنامج، تُدار بصورة منسقة لتحقيق منافع وضبط لا يمكن تحقيقهما بإدارة كل منها منفرداً. وتركز البرامج على الاعتماد المتبادل بين المشاريع والمواءمة الاستراتيجية اللازمة لتحقيق منافع تنظيمية محددة.","الخيارات الأخرى غير صحيحة:","B. يشير التجميع في مكان واحد (Colocation) إلى وضع أعضاء الفريق في موقع فعلي واحد لتعزيز التواصل والتعاون؛ وهو أسلوب لإدارة الفريق، وليس تجميعاً هيكلياً للمشاريع.","C. الحزمة (Suite) ليست مصطلحاً معيارياً في إدارة المشاريع لوصف تجميع المشاريع.","D. تتكون المحفظة من مشاريع وبرامج ومحافظ فرعية وعمليات تُدار كمجموعة لتحقيق أهداف استراتيجية. ورغم أن البرامج غالباً ما تكون جزءاً من محفظة، فإن المحفظة مجموعة أوسع تركز على اختيار العمل وترتيب أولوياته لتحقيق أهداف تجارية عالية المستوى، بينما يركز البرنامج على التسليم المنسق للمشاريع المترابطة."]},"option-0":{"sourceHash":"90920d93e2c7e6323a947c6edb0e31a9702002e329af32a67fea53f221983cb0","ar":["برنامج"]},"option-1":{"sourceHash":"ec1182bcb237f5b19ed53b3c5f93bc3465998cb8bce4ab1abf036558fb710bb2","ar":["تجميع الفريق في مكان واحد (Colocation)"]},"option-2":{"sourceHash":"9c21005014a9eea844541d4c798046faef3683b286eb18bed956b5c6bb41f4a3","ar":["حزمة (Suite)"]},"option-3":{"sourceHash":"1853eb2e9e5ed2bcc1d03b5a49cf407f2e43851363a8ffd0ce5ab7aa37ca8309","ar":["محفظة"]}}},{"id":"vce-1-30","promptHash":"e9683c930b67d479c88f18cd34f78890192a354480779aa29b613972520b2b29","fields":{"prompt":{"sourceHash":"e9683c930b67d479c88f18cd34f78890192a354480779aa29b613972520b2b29","ar":["يفضل مدير مشروع إنشاء شلال خرساني في مدينة ألعاب أن يخطط لكل شيء مقدماً وأن يتبع المنهج الشلالي (Waterfall). لكن العميلة لا تريد تثبيت كل شيء منذ البداية، فقد تغيّر رأيها في عدة جوانب بعد انطلاق المشروع، وتريد التأكد من قدرة مدير المشروع على استيعاب الآثار المترتبة على تلك التغييرات. ما نوع دورة حياة المشروع الذي ينبغي له استخدامه؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"a48ad107c99d0fa44ac9a297ae022d11034d4ef5f2265ef467fce487751fd390","ar":["B. التكيفية","دورة الحياة التكيفية، أو الرشيقة، هي الاختيار الصحيح هنا. ففي النهج التكيفي، يُقسَّم المشروع إلى تكرارات متعددة. ولا تُحدَّد المتطلبات التفصيلية والنطاق ويُعتمدا إلا في بداية كل تكرار، بدلاً من تحديدهما بالكامل دفعة واحدة. ويتيح ذلك للعميلة تغيير رأيها وتطوير المنتج بناءً على التغذية الراجعة مع تقدم المشروع، ويوفر المرونة لإدارة «الآثار المترتبة» على هذه التغييرات.","الخيارات الأخرى غير صحيحة:","A. تشير الضمنية (Tacit) إلى معرفة يصعب نقلها إلى شخص آخر عن طريق الكتابة أو التعبير الشفهي. وليست دورة حياة للمشروع.","C. تشير الصريحة (Explicit) إلى معرفة يمكن التعبير عنها وتدوينها وتخزينها بسهولة. وهي، مثل المعرفة الضمنية، مفهوم مرتبط بإدارة المعرفة، وليست منهجية لدورة حياة المشروع.","D. النهج التنبؤي، أو الشلالي، هو تحديداً ما يفضله مدير المشروع، لكنه غير ملائم لهذا السيناريو لأنه يتطلب نطاقاً ثابتاً مقدماً ويتسم بالجمود، مما يصعّب استيعاب رغبة العميلة في تغيير رأيها طوال المشروع."]},"option-0":{"sourceHash":"623cec8a3016ccbf34967d7ecd534a6c28424e3752ebcb50cdaac7661ffa0129","ar":["الضمنية (Tacit)"]},"option-1":{"sourceHash":"ceb6931ea57cc99912b7ece16f363cc3b42db89fd015d9937d7bb42997dcb663","ar":["التكيفية"]},"option-2":{"sourceHash":"d863c482f7fd7f499980fbce6670b879c413a842d0047ab0afe6ecf777430651","ar":["الصريحة (Explicit)"]},"option-3":{"sourceHash":"666681affe05a8062084fdf30fdaae0d419aaeab57b016e98770385f0ff53c40","ar":["التنبؤية"]}}},{"id":"vce-1-31","promptHash":"0fe2bc988055dc8ad18d487880905ce277b516a00d58164963da03ba41d13620","fields":{"prompt":{"sourceHash":"0fe2bc988055dc8ad18d487880905ce277b516a00d58164963da03ba41d13620","ar":["انضممت حديثاً إلى منظمة بصفتك مدير التسويق. وأُبلغت بأن منتجاً جديداً قد أُنشئ للتو، وعليك طرحه في السوق خلال الشهر المقبل. ويتطلب ذلك بيانات صحفية وإعلانات تلفزيونية وإذاعية وعبر الإنترنت والصحف، وحفل إطلاق كبير بمشاركة شخصية محلية مشهورة واحدة على الأقل. تطلب اجتماعاً مع مدير مشروع للحصول على مشورة بشأن بدء المشروع، لكنك تُبلَّغ بأن المنظمة ليس لديها مدير مشروع، بل منسق مشروع بدوام جزئي فقط. ما الهيكل التنظيمي للمنظمة؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"97f31d512c1430ffd58bd696903c22a9e60f9d743549657c941866191fa14009","ar":["D. مصفوفي ضعيف","في المنظمة المصفوفية الضعيفة، غالباً ما لا يكون دور مدير المشروع وظيفة مخصصة بدوام كامل. وبدلاً من ذلك، قد يحمل الأفراد مسميات مثل «منسق مشروع» أو «ميسّر متابعة المشروع» (Project Expeditor). وتكون صلاحياتهم على الموارد والميزانية محدودة جداً؛ فدورهم إداري أساساً، يركز على التنسيق والتواصل، لا على القيادة الاستراتيجية أو السلطة الموجودة في المنظمة المصفوفية القوية أو الموجّهة نحو المشاريع.","الخيارات الأخرى غير صحيحة:","A. في المنظمة الموجّهة نحو المشاريع، أو القائمة على المشاريع، يتمتع مديرو المشاريع بسلطة واسعة إلى كاملة على موارد المشروع وميزانياته، ويكونون عادةً متخصصين متفرغين بدوام كامل.","B. في المنظمة المصفوفية القوية، يتمتع مديرو المشاريع بدرجة عالية من السلطة، وتكون أدوارهم عادةً مخصصة ومتفرغة، على غرار الهيكل الموجّه نحو المشاريع.","C. مكتب إدارة المشاريع (PMO) هيكل إداري يوفر الدعم والحوكمة للمشاريع؛ وليس في حد ذاته نوعاً من الهياكل التنظيمية كالوظيفي أو المصفوفي أو القائم على المشاريع."]},"option-0":{"sourceHash":"dc52f79f7d246515f1d89e15c2b490cd422dffac76170c92b98020b56ed2e86c","ar":["موجّه نحو المشاريع"]},"option-1":{"sourceHash":"722dd1df10f01e264a9d51f0def544996958f25c5e240301833c5638b151f5dc","ar":["مصفوفي قوي"]},"option-2":{"sourceHash":"fe4f895e2cad63c9172a4af82141977d6fb85b323d0052599b7872deb155ba43","ar":["مكتب إدارة المشاريع (PMO)"]},"option-3":{"sourceHash":"cb1a1b640fcc80eb1c5881e226c6bdde6bae17b95229b47fb4d858a6cd1d97cc","ar":["مصفوفي ضعيف"]}}},{"id":"vce-1-32","promptHash":"6666245dbd32c8349b7b56416f59eeb1effbc8b3660cfc700e8e9effa0a48f61","fields":{"prompt":{"sourceHash":"6666245dbd32c8349b7b56416f59eeb1effbc8b3660cfc700e8e9effa0a48f61","ar":["تعمل مع باحثَين مساعدين لتحديد ما إذا كان تطبيق نظام WiFi في الحي سيعود بالنفع على السكان. وفي إطار هذا الجهد، ستتعاون مع الجهات المختصة للحصول على وثائق حكومية ذات صلة. وستُجري أيضاً مسحاً واسعاً حول كيفية استخدام الناس للنظام، وتُعدّ تقارير من نتائج المسح. ماذا تُسمّي هذا الجهد؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"14be81e605d66c49cba9b8e5d33cf7bd06c163afc7bad027059f66bf6187e6db","ar":["D. مشروع","يُعرَّف المشروع بأنه مبادرة مؤقتة تقدم في نهايتها قيمة من خلال منتج أو خدمة أو نتيجة. وينطبق هذا الوصف على الجهد المذكور لأنه ذو غرض محدد، ويتضمن سلسلة مهام منسقة، مثل التعاون مع الجهات المختصة وإجراء المسوح وإعداد التقارير، وينتج عنه مخرج فريد، أي الدراسة أو التقرير المستخدم لتحديد جدوى تطبيق WiFi وفائدته.","الخيارات الأخرى غير صحيحة:","A. العمليات التشغيلية عمليات مستمرة ومتكررة تدعم استمرار الأعمال. ولا تكون لها بداية ونهاية محددتان على النحو نفسه الذي يميز المشروع.","B. وC. المسح والدراسة البحثية مهام أو أساليب محددة ضمن نطاق المشروع، لكنهما لا يصفان الجهد بأكمله، الذي يشمل التنسيق والتفاعل مع أصحاب المصلحة وإنتاج نتيجة شاملة."]},"option-0":{"sourceHash":"00c3527cab737dcf4c8182b0a0b4293ec323e68f34e55fa008d982a97d021b19","ar":["عملية تشغيلية"]},"option-1":{"sourceHash":"f859bae76e59ae30f0fd808e71960a8e8c4bc2890186a228185f3e782d90a048","ar":["مسحاً"]},"option-2":{"sourceHash":"6e8553a95b6e299cd14eaad61308f082408c0bd649793ec36cf84379ba38306a","ar":["دراسة بحثية"]},"option-3":{"sourceHash":"acf2f1db562dbd0b9b58e0c3d4df6e95e2fd97165cf3b93def97b981e0bb3130","ar":["مشروعاً"]}}},{"id":"vce-1-33","promptHash":"738572adf1672454e98474d5553945dd3f416cf496bfcad131cd3be3bd3e2b64","fields":{"prompt":{"sourceHash":"738572adf1672454e98474d5553945dd3f416cf496bfcad131cd3be3bd3e2b64","ar":["أيٌّ مما يلي يصف دور راعي المشروع على أفضل وجه؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"31cef15abda78abab4a4c387ed4d8effbee942455d4011fcb64c35b273aa1e03","ar":["B. راعي المشروع مسؤول عن توفير التمويل للمشروع","راعي المشروع فرد أو مجموعة توفر الموارد والدعم للمشروع وتتحمل المساءلة عن تمكين نجاحه. ويشمل دوره الأساسي دعم المشروع داخل المنظمة وتوفير التمويل اللازم أو تأمينه واعتماد ميثاق المشروع. وهو أيضاً صاحب المصلحة الرئيسي المسؤول عن التصريح بالمشروع عند انطلاقه وتقديم التوجيه عالي المستوى.","الخيارات الأخرى غير صحيحة:","A. مدير المشروع هو المسؤول عن إدارة المشروع. ويوفر الراعي الدعم، لكنه لا يدير التنفيذ اليومي.","C. مدير المشروع وفريق المشروع، بدعم من إدارة ضمان الجودة في كثير من الأحيان، مسؤولون عن إدارة جودة تسليمات المشروع.","D. رغم أن الراعي قد يساعد في تحديد أصحاب المصلحة على المستوى الرفيع، فإن مسؤولية تحديد جميع أصحاب المصلحة وتحليلهم وإشراكهم طوال دورة حياة المشروع تقع على مدير المشروع."]},"option-0":{"sourceHash":"5dcb7dd998e5d539ebbcfd1d3e96b4739853b08e04a584281ca45de24630e665","ar":["راعي المشروع مسؤول عن إدارة المشروع"]},"option-1":{"sourceHash":"d54cde8a72ad70d11bb8b92690468cdc367808d7da33b525ceb78e1568ef3df8","ar":["راعي المشروع مسؤول عن توفير التمويل للمشروع"]},"option-2":{"sourceHash":"aa1eacef52fae47f54261276c05febb336f9a877ae864475d337038cee54c062","ar":["راعي المشروع مسؤول عن إدارة جودة التسليمات"]},"option-3":{"sourceHash":"bea92bd056eb947539de8261a6f156ecdff4b9251ae145a210f08851f1ceb64e","ar":["راعي المشروع مسؤول عن تحديد أصحاب المصلحة الرئيسيين"]}}},{"id":"vce-1-34","promptHash":"53ff9b902933ffa28e863fa02df6859c60506541018fb322b655c58546e58e09","fields":{"prompt":{"sourceHash":"53ff9b902933ffa28e863fa02df6859c60506541018fb322b655c58546e58e09","ar":["عُيّنت مدير مشروع في منظمة لنظم المعلومات، ولست على دراية بسياساتها وإجراءاتها. إذا أردت معرفة المزيد عن إجراءات المنظمة العامة لإدارة المسائل، فأيٌّ مما يلي ينبغي مراجعته؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"45a4436a10dc040376fe316bbf335ad5b0b6ce6e132b409e0f2135b7e06b3ae1","ar":["D. أصول العمليات التنظيمية (OPA)","تشمل أصول العمليات التنظيمية (OPA) الخطط والعمليات والسياسات والإجراءات وقواعد المعرفة الخاصة بالمنظمة المنفذة والمستخدمة فيها. وبما أن إجراءات إدارة المسائل سياسات داخلية ومعرفة مؤسسية بكيفية أداء العمل، فإنها تُصنَّف ضمن أصول العمليات التنظيمية. وهذه الأصول أدلة «كيفية العمل» لإدارة المشاريع في تلك الشركة تحديداً.","الخيارات الأخرى غير صحيحة:","A. سجل المسائل وثيقة مشروع تُستخدم لتتبع مسائل محددة وإدارتها في مشروع معين؛ ولا يحتوي على الإجراءات التنظيمية العامة لإدارة المسائل.","B. خطة إدارة المشروع وثيقة شاملة تحدد كيفية تنفيذ المشروع ومراقبته وضبطه، لكنها عادةً ما تحيل إلى إجراءات أصول العمليات التنظيمية القائمة، بدلاً من احتوائها على السياسات التنظيمية العامة عالية المستوى نفسها.","C. تشير العوامل البيئية للمؤسسة (EEF) إلى ظروف لا تخضع لسيطرة فريق المشروع، مثل الثقافة التنظيمية وظروف السوق واللوائح الحكومية والبنية التحتية. ورغم تأثر الإجراءات بالبيئة، فإن الوثائق الإجرائية نفسها تُعد من أصول العمليات التنظيمية."]},"option-0":{"sourceHash":"f4294f72f4c2a834b91e5fbe220ca1fc4ede7fd987ed3ecd59f41db39e465d4c","ar":["سجل المسائل"]},"option-1":{"sourceHash":"4a092d2a4621953fc7578ef3c7183899ed392b464ada539f5f835f4de5552208","ar":["خطة إدارة المشروع"]},"option-2":{"sourceHash":"b7777bdcfa72d0e324a4249b5dcd48270b659a648c4becaeafe7c542c18f5f6e","ar":["العوامل البيئية للمؤسسة (EEF)"]},"option-3":{"sourceHash":"ec9b6f15371400ba0790427d82966b1ad9199a5aa8d73be74775fb34537c0ccd","ar":["أصول العمليات التنظيمية (OPA)"]}}},{"id":"vce-1-35","promptHash":"2e6b7275e32bd5fe7c5bf8af7f8aec5ed3fef57298d2df4533c6607ece7fd260","fields":{"prompt":{"sourceHash":"2e6b7275e32bd5fe7c5bf8af7f8aec5ed3fef57298d2df4533c6607ece7fd260","ar":["يقود مدير مشروع تصميم نظام حاسوبي جديد متطور وتطويره، والمشروع في المرحلة الثانية من خمس مراحل. ويتأخر المشروع عن الجدول الزمني ويتجاوز الميزانية بدرجة كبيرة بسبب قوة قاهرة. ويُنفَّذ داخلياً للحفاظ على السيطرة على التقنية المملوكة التي ستوفر ميزة تنافسية. وقد وصل المشروع إلى بوابة مرحلة. ما الغرض من إجراء مراجعة بوابة المرحلة؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"fd163e327422b9db46958983fff58b54fd0526b0c114f373ad61bee7d68e5b1d","ar":["A. مقارنة أداء المشروع بوثائق الأعمال لتحديد ما إذا كان ينبغي الانتقال إلى المرحلة التالية، أو إنهاء المشروع، أو إعادة المرحلة","بوابة المرحلة، المعروفة أيضاً بمراجعة المرحلة أو نقطة الإيقاف، نقطة مراجعة مجدولة في نهاية مرحلة من مراحل المشروع. وغرضها الأساسي تقييم استمرار جدوى المشروع وأدائه. ويقيّم أصحاب المصلحة استمرار توافقه مع دراسة الجدوى التجارية الأصلية والأهداف الاستراتيجية المحددة في وثائق الأعمال، ثم يقررون المسار الأنسب: الانتقال إلى المرحلة التالية، أو إنهاء المشروع إذا لم يعد مجدياً، أو إعادة المرحلة الحالية إذا لم تُستوفَ معايير النجاح.","الخيارات الأخرى غير صحيحة:","B. تعديل خطوط الأساس من وظائف عملية ضبط التغيير أو مراقبة المشروع، وليس الهدف الأساسي لاتخاذ القرار الاستراتيجي عند بوابة المرحلة.","C. تخطيط الموارد وتقديرها أنشطة تشغيلية تُنفَّذ أثناء التخطيط؛ وليست الغرض المحوري لبوابة المرحلة، التي تمثل نقطة قرار بالاستمرار أو التوقف.","D. رغم مراجعة التسليمات غالباً عند بوابات المراحل، فإن «قبول العميل» عادةً مهمة أكثر تفصيلاً تتعلق بمجال أداء التسليم أو إغلاق حزم عمل محددة، لا بالقرار الاستراتيجي بشأن استمرار المشروع بأكمله."]},"option-0":{"sourceHash":"a7958f8d4d667bb27ae51c0d1caba6c9520ee9ea46eeb1598e7e4c1e5f91a009","ar":["مقارنة أداء المشروع بوثائق الأعمال لتحديد ما إذا كان ينبغي الانتقال إلى المرحلة التالية، أو إنهاء المشروع، أو إعادة المرحلة"]},"option-1":{"sourceHash":"d280e64f8e318de2be65647cad49013f4163b875e0e6b40374436aa3727ba39a","ar":["تعديل خطي أساس الجدول الزمني والتكلفة استناداً إلى الأداء السابق"]},"option-2":{"sourceHash":"4d32d5f724798052f2cd4f07fda26ed4b2624a90d9206f9ab52bb7c3d436c92c","ar":["تحديد عدد الموارد اللازمة لإتمام المشروع وفقاً لخط أساس المشروع"]},"option-3":{"sourceHash":"5d67cbaa24d8b0c72b04f1f9cdeb5d5a2eccae174c81278fc45d17ad02dd1d1f","ar":["الحصول على قبول العميل لتسليمات المشروع"]}}},{"id":"vce-1-36","promptHash":"724acd5daf5fd0ffaf67b583eb74b83d33bdd3218ceca6d8db2a3f83c2c6db19","fields":{"prompt":{"sourceHash":"724acd5daf5fd0ffaf67b583eb74b83d33bdd3218ceca6d8db2a3f83c2c6db19","ar":["توثق دراسة الجدوى التجارية الحاجة التجارية وتحليل التكلفة والمنفعة الذي يبرر المشروع. أيٌّ مما يلي يصف مسؤولية مدير المشروع تجاه دراسة الجدوى التجارية للمشروع على أفضل وجه؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"74c0d0e912e1f2d551096b08a1c015303b4c03b4f3d818cd5a7917e83ed01910","ar":["C. يجوز لمدير المشروع تقديم توصيات للحفاظ على توافق دراسة الجدوى التجارية للمشروع مع غايات المنظمة وأهدافها.","دراسة الجدوى التجارية وثيقة أعمال يُعدّها راعي المشروع أو إدارة المنظمة ويحافظ عليها، وليس مدير المشروع. لكن إلمام مدير المشروع الوثيق بالتقدم والمخاطر والأداء يجعله في أفضل موقع لمراقبة استمرار تقديم المشروع للقيمة المحددة في الدراسة. لذلك يؤدي دور المستشار، فيحدد انحراف مسار المشروع عن الأهداف الاستراتيجية، ويقدم توصيات لضمان المواءمة.","الخيارات الأخرى غير صحيحة:","A وB. لا يملك مدير المشروع صلاحية تحديث دراسة الجدوى التجارية أو تغييرها، لأنها وثيقة على مستوى الحوكمة يحتفظ بها الراعي أو مالك الأعمال.","D. يجري إعداد دراسة الجدوى التجارية قبل البدء الرسمي للمشروع. ورغم إمكانية الاستعانة بخبرة مدير مشروع أثناء إعدادها، فإنه ليس عموماً المسؤول عن إعدادها."]},"option-0":{"sourceHash":"714e8662e7da8d98d26bef4fd76a5551ef12a9dac5508542baff771fa83e91c3","ar":["تحديث دراسة الجدوى التجارية في نهاية كل مرحلة"]},"option-1":{"sourceHash":"0ac7976ebdb9dffcbf23a7225178541744be7cb8889b88fc614b16a83ae81cff","ar":["إجراء تغييرات على دراسة الجدوى التجارية عند الحاجة"]},"option-2":{"sourceHash":"00396a19ae1cef68839b7f9b0563e36f5ae9c8137294e280ce04e633793b5045","ar":["يجوز لمدير المشروع تقديم توصيات للحفاظ على توافق دراسة الجدوى التجارية للمشروع مع غايات المنظمة وأهدافها."]},"option-3":{"sourceHash":"6101542b38e9db966dafbb727c1050961fe2a5ec7148306d8d8d6cfa431d7209","ar":["إعداد دراسة الجدوى التجارية للمشروع"]}}},{"id":"vce-1-37","promptHash":"1ce01872f3cc75fcf487893628ebbd77e24558d5ccf2552e70e00118021b2ad5","fields":{"prompt":{"sourceHash":"1ce01872f3cc75fcf487893628ebbd77e24558d5ccf2552e70e00118021b2ad5","ar":["تستخدم منظمة نهج تسليم هجيناً لمشروع أعمال. وقد ترقّى مالك المنتج، الذي كان يدير المشروع أيضاً، إلى منصب أعلى. وانضم قائد مشروع جديد. ما وثيقة العمل التي ينبغي للقائد استخدامها للتأكد من تحديد منافع المشروع؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"0a909d0b8a5e265762a119219326cd0b6156a567bdb506b0e9d41783e01962f5","ar":["B. دراسة الجدوى التجارية","دراسة الجدوى التجارية هي الوثيقة الأساسية التي تبرر وجود المشروع. فهي تسجل صراحةً الحاجة التجارية وتحليل التكلفة والمنفعة والمواءمة الاستراتيجية، والأهم، منافع المشروع المنشودة التي تتوقع المنظمة تحقيقها. وعند تولي قائد جديد المسؤولية، تكون هذه الدراسة المرجع الأساسي لفهم سبب المشروع وضمان استمرار تركيز الفريق على تقديم تلك المنافع الأصلية.","الخيارات الأخرى غير صحيحة:","A. قائمة أعمال المنتج قائمة مرتبة حسب الأولوية بالميزات والوظائف ومتطلبات المنتج. ورغم تسجيلها للعمل المطلوب، فإنها لا تفصل المنافع التجارية عالية المستوى أو المبرر الاستراتيجي للمشروع.","C. بيان العمل (SOW) وثيقة وصفية تركز على التسليمات ونطاق العمل ومتطلبات المشروع. وتحدد ما يجري بناؤه، لكنها عادةً تفتقر إلى المبرر التجاري الاستراتيجي وتحليل المنافع الموجودين في دراسة الجدوى التجارية.","D. مخطط باريتو أداة لضبط الجودة، في صورة رسم بياني تكراري، تُستخدم لترتيب المشكلات أو أسبابها حسب الأولوية بناءً على التكرار، وفق قاعدة 80/20. ويُستخدم لتحليل البيانات أثناء التنفيذ، لا لتحديد المنافع التجارية."]},"option-0":{"sourceHash":"1f61e45b285143334d1bc94e8839b8355d3a3391cae8531f5b11ef4c075857df","ar":["قائمة أعمال المنتج"]},"option-1":{"sourceHash":"79ee36f21b97cdf1d26caed96b9cd16045e3c245acee111a7a614bb1815d5026","ar":["دراسة الجدوى التجارية"]},"option-2":{"sourceHash":"812eab33d102cbf909bca2028bd58bef35656f560d3aa5a7830a75a2ad4f4cfa","ar":["بيان العمل (SOW)"]},"option-3":{"sourceHash":"21f53325ca33681d3058fc8548f4343dd45108dd1ec3678bd18c638d416e6bef","ar":["مخطط باريتو"]}}},{"id":"vce-1-38","promptHash":"e9b61d0ef6fd8c34a828eaab9df3cbfb8870f8e5f81074a993491248f7292cf7","fields":{"prompt":{"sourceHash":"e9b61d0ef6fd8c34a828eaab9df3cbfb8870f8e5f81074a993491248f7292cf7","ar":["تضع مناهج إدارة المشاريع التقليدية مدير المشروع في مركز تنسيق المشروع، وتجعله مسؤولاً عن تتبعه وإعداد تقاريره. لكن هذا النهج لا يلائم:"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"821210b7c4ab1c8d22c8957e7575aa8d65b2513d9d1182711883ac98f22b9f31","ar":["D. المشاريع كثيرة التغيير التي يتجاوز تعقيدها قدرة شخص واحد على الإدارة","في الإدارة التقليدية، أو التنبؤية، غالباً ما يكون مدير المشروع المنسق الأساسي ونقطة الاتصال المركزية. لكن في البيئات كثيرة التغيير، أي التكيفية أو الرشيقة، غالباً ما يتجاوز التعقيد وسرعة التغيير قدرة فرد واحد على التتبع والإدارة. وتتطلب هذه المشاريع نهجاً تعاونياً يُمكَّن فيه الفريق من التنظيم الذاتي وتنسيق عمله واتخاذ القرارات محلياً للاستجابة للمستويات المرتفعة من عدم اليقين والتغيير.","الخيارات الأخرى غير صحيحة:","تصف الخيارات A وB وC خصائص تتوافق جيداً مع المناهج التقليدية التنبؤية. فالمشاريع التنبؤية عادةً ما تنجح مع التخطيط المسبق والنطاقات المحددة جيداً والجداول الزمنية التفصيلية المستندة إلى خطوط الأساس، وجميعها قابلة للإدارة والإشراف الفعال من مدير مشروع مركزي."]},"option-0":{"sourceHash":"e0fadbccd854b631b45ae5cf0f96fd9705e862436c8f6fa84b40e2347c58bb0b","ar":["المشاريع التي تتطلب إنجاز التخطيط مقدماً."]},"option-1":{"sourceHash":"8d85f03b251cc105a80464198e9d23bde1bfa0796c33186c1ddf91bb1848fe95","ar":["المشاريع قليلة التغيير التي قدمت فيها منظمة العميل نطاقاً تفصيلياً."]},"option-2":{"sourceHash":"10f9199fad9373d88435d2f7544ee8aff4a0d700b3f28c838cf9d861b1d2dea2","ar":["المشاريع التي تتطلب إعداد جداول زمنية تفصيلية واعتمادها من العملاء."]},"option-3":{"sourceHash":"9a60d73ce6f7a8222883402d5838af121cddedda2b3f4c694d43954c56eb46ac","ar":["المشاريع كثيرة التغيير التي يتجاوز تعقيدها قدرة شخص واحد على الإدارة"]}}},{"id":"vce-1-39","promptHash":"c1eea55ed67eb76d73b81a126b9d99abc9ed921024113399376b0e5f79bc49e7","fields":{"prompt":{"sourceHash":"c1eea55ed67eb76d73b81a126b9d99abc9ed921024113399376b0e5f79bc49e7","ar":["يُعدّ مدير مشروع إطار حوكمة يعزز كفاءة المشروع وفاعليته. ويريد البدء بجميع الموارد القائمة والأطر المنظمة أو المعلومات المفيدة الأخرى التي قد تكون متاحة.","ماذا ينبغي لمدير المشروع فعله؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"b60eaf879b1d2e184a0afcdc2500eea938edd549e2b1ab2b2ac654015704a648","ar":["C. الرجوع إلى أصول العمليات التنظيمية (OPAs) من مشاريع مماثلة.","يمكن أن تكون أصول العمليات التنظيمية، بما فيها وثائق العمل أو الممارسات أو المعرفة المكتسبة من مشاريع داخلية سابقة، مدخلات قيّمة لحوكمة مشروع جديد. وبمراجعة وثائق مثل الجداول الزمنية للمشاريع المكتملة والدروس المستفادة، من المرجح أن يجد مدير المشروع معلومات مفيدة لتوجيه المشروع الجديد.","الخيارات الأخرى غير صحيحة.","قد تكون دراسة المعايير التنظيمية مناسبة بحسب طبيعة المشروع. لكن لأن هذه المعايير لا تخضع للسيطرة المباشرة للفريق، فإنها تُصنَّف ضمن العوامل البيئية للمؤسسة، لا أصول العمليات التنظيمية.","وكما في معايير الجهات التنظيمية، قد تقدم البحوث الأكاديمية مدخلات مفيدة للفريق، لكنها تُعد من العوامل البيئية للمؤسسة لا من أصول العمليات التنظيمية.","قد يستفيد المشروع من إدراج أدوات تقنية المعلومات مثل برامج الجدولة. لكن حتى الأدوات المملوكة للمنظمة لا تخضع للسيطرة المباشرة للفريق، لذا تُصنَّف ضمن العوامل البيئية للمؤسسة، لا أصول العمليات التنظيمية."]},"option-0":{"sourceHash":"99952a4942f5df4fac43f5fc710db7e81331f6195b3eb3ef1bd0dcfc6c3ee884","ar":["دراسة معايير الجهات التنظيمية المرتبطة بهذا النوع من المشاريع"]},"option-1":{"sourceHash":"9164196f591e26e2f009b3c5717448f535b2706035f4d9bca86225ab3c6d116f","ar":["مراجعة البحوث الأكاديمية، مثل الدراسات القطاعية، المتعلقة بموضوع المشروع."]},"option-2":{"sourceHash":"c5c7b454b701196a65fbc1c9a5138e6628d5658cd2e075a1666e1bffd61934b3","ar":["الرجوع إلى أصول العمليات التنظيمية (OPAs) من مشاريع مماثلة."]},"option-3":{"sourceHash":"4650f48691131e017d7d30a2b6946a3e002b9613315d4de52ccc73190444986d","ar":["إدراج أدوات تقنية المعلومات، مثل برامج الجدولة."]}}},{"id":"vce-1-40","promptHash":"62e5850e79c41f33511b351ffa2ac8d720c03daa2748b2766c47c28081b45962","fields":{"prompt":{"sourceHash":"62e5850e79c41f33511b351ffa2ac8d720c03daa2748b2766c47c28081b45962","ar":["تطلق شركة تصنيع كبرى مبادرة جديدة مربحة يجب أن تستوفي لوائح وسياسات داخلية وخارجية صارمة. وفي إطار التحضير، أجرت المنظمة مسوحاً عديدة وجمعت بيانات قيّمة لتوجيه إدارة المشروع. ويحتاج مدير المشروع إلى التأكد من أن المنظمة تحوكم المشروع بفاعلية.","ماذا ينبغي لمدير المشروع فعله؟"]},"section":{"sourceHash":"9570ff913450e569c414d59c728e4c77b75a7e5da38f90740409466f2802beb7","ar":["الاختبار A"]},"explanation":{"sourceHash":"e00fac30def184cddef7b72749db56b258f4843e7987a5afe5c233806a369c2b","ar":["C. فحص أصول العمليات التنظيمية (OPAs) لتحديد الهيكل والقواعد والإجراءات والسياسات التي يجب أن يتبعها المشروع.","تشمل أصول العمليات التنظيمية أي وثيقة عمل أو ممارسة أو معرفة لدى المنظمات المنفذة المشاركة في المشروع، بما في ذلك، على سبيل المثال لا الحصر، السياسات والعمليات والإجراءات ومستودعات المعرفة التنظيمية. وتدخل هذه الأصول في كثير من عمليات إدارة المشاريع، وتوجه إدارة المشروع وتؤثر فيها.","الخيارات الأخرى غير صحيحة:","ميثاق المشروع خاص بالمشروع، ولا يتضمن جميع السياسات والموارد التنظيمية ذات الصلة. وإعداد الميثاق ضروري لعمل فريق المشروع وتحديد صلاحيات مديره، لكنه لا يوفر له تلقائياً البيانات والمعلومات ذات الصلة. ويجب على مدير المشروع استخدام الصلاحية الممنوحة له بموجب الميثاق للوصول إلى أصول العمليات التنظيمية والاستفادة منها وتزويد فريقه بالمعلومات اللازمة.","قد يستخدم فريق المشروع أصول العمليات التنظيمية عند إعداد خطة إدارة الموارد لضمان توافق جميع الموارد المختارة مع السياسات الداخلية والخارجية والتزامها بنتائج البيانات المجمعة. ولا تضمن خطة إدارة الموارد في حد ذاتها الحوكمة الفعالة.","قد تكون بيانات أداء العمل للمشاريع السابقة والحالية جزءاً من أصول العمليات التنظيمية، لكن يجب تحليلها مع وثائق العمل والبيانات الأخرى لفهم النطاق الكامل لإدارة المشروع."]},"option-0":{"sourceHash":"fcdb7b8bf203c2d397e19682330fad81059d02150d2f6a3dcf6f7e6079968b56","ar":["تطبيق ميثاق مشروع لإضفاء الصفة الرسمية على صلاحية مدير المشروع في الوصول إلى بيانات المنظمة واستخدامها."]},"option-1":{"sourceHash":"38673861c1f6bd45dc1157577878757c6fff0bebdca1cdeee45df685eeb0cda2","ar":["إعداد خطة لإدارة الموارد لتحديد الموارد اللازمة وضمان استيفائها لجميع السياسات الداخلية"]},"option-2":{"sourceHash":"07116cf8581c9fd53b3399a5cd1be56ef2d5ae29b5eac5bbd77ee3d25b523d6b","ar":["فحص أصول العمليات التنظيمية (OPAs) لتحديد الهيكل والقواعد والإجراءات والسياسات التي يجب أن يتبعها المشروع."]},"option-3":{"sourceHash":"a81614ef2a7f33a299df42f3ab295b0327993bc8f7c7972a3bbb91695909e1c3","ar":["استخدام بيانات أداء العمل لتحليل مؤشرات الأداء الرئيسية وضمان التزام فريق المشروع باللوائح الداخلية"]}}}];
